export const istorijaSearch: { slug: string; chunks: { text: string; headingId: string; headingText: string }[] }[] = [{"slug":"Abrahin-slon","chunks":[{"text":"Prema Britanici, Abrahina vladavina okončana je 575. godine, kada su Persijanci napali Jemen, što znači da je bio živ u vreme Poslanikovog ﷺ rođenja. Pustinjski slonovi mogu preći između 99 i 149 kilometara dnevno i podneti žeđ do četiri dana, pa bi put od oko hiljadu kilometara trajao svega pet do deset dana. Uz to, karte pokazuju područja sa rastinjem, bunarima i padavinama duž tog puta.","headingId":"","headingText":""},{"text":"Prva primedba Abraha je umro decenijama pre Poslanika ﷺ Enciklopedija Britanika navodi da je Abrahina vladavina okončana 575. godine, kada su persijski Sasanidi napali Jemen. Encyclopedia Britannica, odrednica Abraha. To znači da je Abraha bio živ u vreme Poslanikovog ﷺ rođenja, a ne decenijama pre njega.","headingId":"prva-primedba-abraha-je-umro-decenijama-pre-poslanika-","headingText":"Prva primedba - Abraha je umro decenijama pre Poslanika ﷺ"},{"text":"Druga primedba slon ne može preći put od Jemena do Meke Pustinjski slonovi mogu preći između 99 i 149 kilometara dnevno i mogu podneti žeđ do četiri dana. Rastojanje od otprilike hiljadu kilometara pri takvoj brzini iziskivalo bi svega pet do deset dana. Karte pokazuju područja sa rastinjem, izvore vode i pojaseve padavina duž puta od Jemena do Meke, što protivreči tvrdnjama o potpunoj pustoši.","headingId":"druga-primedba-slon-ne-moze-preci-put-od-jemena-do-meke","headingText":"Druga primedba - slon ne može preći put od Jemena do Meke"},{"text":"Treća primedba hrišćanska tradicija ne poznaje hodočašće crkvi Izraz hadž na arapskom znači posetu nekom mestu. Hrišćani svake godine posećuju Crkvu Vaskrsenja, čime se pokazuje da hodočasnički običaji postoje u svim verama.","headingId":"treca-primedba-hriscanska-tradicija-ne-poznaje-hodocasce-crkvi","headingText":"Treća primedba - hrišćanska tradicija ne poznaje hodočašće crkvi"},{"text":"Četvrta primedba zašto Bog nije zaštitio Kabu od karmata Karmati Kabu uopšte nisu razorili. Oni su čak vratili i Crni kamen koji su bili odneli.","headingId":"cetvrta-primedba-zasto-bog-nije-zastitio-kabu-od-karmata","headingText":"Četvrta primedba - zašto Bog nije zaštitio Kabu od karmata"},{"text":"Peta primedba nema geoloških tragova vojske ni kamenja Kamenje tokom 1500 godina prolazi kroz mehaničko raspadanje, hemijsko raspadanje, poplave i zatrpavanje peskom, što njegovo pronalaženje čini krajnje teškim.","headingId":"peta-primedba-nema-geoloskih-tragova-vojske-ni-kamenja","headingText":"Peta primedba - nema geoloških tragova vojske ni kamenja"},{"text":"Šesta primedba nema natpisa o pohodu slona ka Meki Predislamski arapski pesnici, među njima Abdul Muttalib, Talib ibn Ebu Talib i Nafil ibn Habib, zabeležili su događaj sa slonom u svojoj poeziji.","headingId":"sesta-primedba-nema-natpisa-o-pohodu-slona-ka-meki","headingText":"Šesta primedba - nema natpisa o pohodu slona ka Meki"},{"text":"Sedma primedba Abrahina vojska umrla je od bolesti, a ne od ptica Njegove vojnike zadesila je smrtonosna bolest, a to su bile boginje… To su bile ptice iz Allahove vojske. Najveći deo vojske je stradao. Izvor: Ibn Ašur. Ibn Ašur, Et Tahrir vet tenvir.","headingId":"sedma-primedba-abrahina-vojska-umrla-je-od-bolesti-a-ne-od-ptica","headingText":"Sedma primedba - Abrahina vojska umrla je od bolesti, a ne od ptica"},{"text":"Osma primedba zašto Abraha nije razorio ostale kabe Takozvana Kaba plemena Havazin uopšte ne postoji. Takozvana Kaba u Taifu bila je zapravo idol Lat. Takozvana Kaba u Sindadu nalazila se u Iraku, do koje se moralo proći kroz Meku. Te tvrdnje, dakle, počivaju na izmišljotinama ili na geografskim nemogućnostima.","headingId":"osma-primedba-zasto-abraha-nije-razorio-ostale-kabe","headingText":"Osma primedba - zašto Abraha nije razorio ostale kabe"},{"text":"Deveta primedba ime Abraha nije abisinsko Enciklopedija islama navodi da je Abraha zapravo Abraham na etiopskom jeziku, i da je to bilo uobičajeno ime za hrišćane u tom kraju. Encyclopaedia of Islam, odrednica Abraha.","headingId":"deveta-primedba-ime-abraha-nije-abisinsko","headingText":"Deveta primedba - ime Abraha nije abisinsko"},{"text":"Deseta primedba kakvu vojnu vrednost slonovi uopšte imaju Vojskovođe u starom veku, među njima Pir Epirski, Aleksandar Veliki i Sasanidi, koristili su ratne slonove. List Illustrated London News navodi da je debeo sloj kože štitio vojnike na slonu, uz istovremeno bolji pregled bojišta. The Illustrated London News.","headingId":"deseta-primedba-kakvu-vojnu-vrednost-slonovi-uopste-imaju","headingText":"Deseta primedba - kakvu vojnu vrednost slonovi uopšte imaju"}]},{"slug":"Andaluzija-i-oslobodjenje-od-vizigotske-vlasti","chunks":[{"text":"Pod vizigotskom vlašću Andaluzija je trpela varvarsku upravu, nepismenost je bila osnovna odlika kraljevstva, a položaj robova bio je nepodnošljiv. Nakon arapskog osvajanja položaj robova je uzdignut, prisilni rad ukinut, a poljoprivreda je procvetala. Stanli Lejn Pul navodi da je civilizacija Andaluzije bila potpuno arapska, a princ Čarls da je Španija pod arapskom vlašću bila najcivilizovanija zemlja na svetu.","headingId":"","headingText":""},{"text":"Stanje Andaluzije pod vizigotskom vlašću Pod vizigotskom vlašću Andaluzija je trpela varvarsku upravu i sve vrste muke, bez ikakve civilizacije vredne pomena. Aldo Mieli, Znanje kod Arapa. Hrišćansko sveštenstvo dokumentovalo je široku pokvarenost i moralno propadanje vladajućeg vizigotskog sloja. Reinhart Dozy, Studije o političkoj i književnoj istoriji Španije. Položaj robovskog sloja bio je nepodnošljiv u vizigotsko doba. Izvor: Dozi. Reinhart Dozy, isto delo. Bogatstvo je gotovo hiljadu godina, pod rimskom i vizigotskom vlašću, bilo skoncentrisano u rukama manjine. Vizigoti su bili doseljenici iz petog veka nove ere i prema domorodačkim Andalužanima koristili su ponižavajuće nazive. The Non Jewish Origins of the Sephardic Jews, str. 76; Concise Encyclopedia of World History, str. 271. Nepismenost je bila osnovna odlika vizigotskog kraljevstva na","headingId":"stanje-andaluzije-pod-vizigotskom-vlascu","headingText":"Stanje Andaluzije pod vizigotskom vlašću"},{"text":"Iberijskom poluostrvu. Izvor: Rozamond Makiterik. Rosamond McKitterick, The Uses of Literacy in Early Mediaeval Europe, str. 120 122 i 127.","headingId":"stanje-andaluzije-pod-vizigotskom-vlascu","headingText":"Stanje Andaluzije pod vizigotskom vlašću"},{"text":"Arapsko muslimansko osvajanje i oslobođenje Latinske istorije osvajače muslimane nazivaju sirijskim Arapima. Izvor: Dozi. Reinhart Dozy, Recherches sur l'Histoire et la Littérature de l'Espagne, tom 1, str. 4 i 20. Tokom prvih četiristo godina arapske vlasti nad Španijom, njihovo postupanje prema Špancima bilo je najblaže i najmilostivije. Izvor: Doroti Louder. Dorothy Loader, Spain, Its People and Land, str. 50. Nakon osvajanja, položaj robova je uzdignut, dozvoljena je prodaja imovine, prisilni rad je okončan, a poljoprivreda je procvetala. Reinhart Dozy, Muslimani u Andaluziji, tom 1, str. 38 49. Iberci su prihvatali islam u velikom broju. Historia Literaria de España, tom II, str. 26, Madrid 1768; Brian A. Catlos, The Victors and the Vanquished.","headingId":"arapsko-muslimansko-osvajanje-i-oslobodjenje","headingText":"Arapsko muslimansko osvajanje i oslobođenje"},{"text":"Civilizacija islamske Andaluzije Španija je, pod arapskom vlašću, bila najcivilizovanija zemlja na svetu. Izvor: Čarls, princ od Velsa, Oksford, 1999. Charles, Prince of Wales, predavanje, Oksford, 1999. Civilizacija Andaluzije bila je potpuno arapska. Izvor: Stanli Lejn Pul. Stanley Lane Poole, The Story of the Arabs in Spain, str. 40. Svi Andalužani, i mladi i stari, i muslimani i nemuslimani, znali su da čitaju i pišu. Izvor: Civilizacija muslimana u Španiji. Civilizacija muslimana u Španiji, str. 85. Abdur Rahman en Nasir opisan je kao najveći kralj u svim razdobljima Evrope. Lévi Provençal, navedeno u: Arthur Koestler, The Thirteenth Tribe, str. 68.","headingId":"civilizacija-islamske-andaluzije","headingText":"Civilizacija islamske Andaluzije"},{"text":"Pitanje takozvane rekonkviste Pelajo i gotski velikaši povukli su se na sever, da bi kasnije ponovo nametnuli stranu vlast. Britannica, odrednica Pelayo, kralj Asturije. Takozvana rekonkvista predstavljala je, dakle, gotsko, a kasnije germansko ponovno nametanje strane vlasti nad pomuslimanjenim domorodačkim stanovništvom. Islamsko razdoblje bilo je za domorodačko stanovništvo razdoblje oslobođenja, pismenosti i blagostanja.","headingId":"pitanje-takozvane-rekonkviste","headingText":"Pitanje takozvane rekonkviste"}]},{"slug":"Andaluzija-je-arapska-civilizacija","chunks":[{"text":"Andaluzija je arapska civilizacija koju su izgradili Sirijci, a Sirijci su sebe smatrali Arapima i baštinu i civilizaciju Andaluzije smatrali arapskom. Gistav le Bon navodi da su Arapi činili misaonu aristokratiju i civilizacijski činilac, dok su se Berberi mešali sa srednjim i nižim slojevima. Mozhajm navodi da su Arapi Andaluzije bili izvor znanja Evropi u medicini, astronomiji i obrazovanju od desetog veka nadalje. Andaluzija je arapska civilizacija koju su izgradili Sirijci, a Sirijci su sebe smatrali Arapima, smatrajući baštinu i civilizaciju Andaluzije arapskom.","headingId":"","headingText":""},{"text":"Gistav le Bon Arapi su činili misaonu aristokratiju i civilizacijski činilac, dok su se Berberi mešali sa srednjim i nižim slojevima. Izvor: Gistav le Bon. Gustave Le Bon, Civilizacija Arapa, str. 281.","headingId":"gistav-le-bon","headingText":"Gistav le Bon"},{"text":"Johan fon Mozhajm Johan fon Mozhajm primećuje da su Arapi Andaluzije duboko uticali na Evropu i da su od desetog veka nadalje bili izvor znanja u medicini, astronomiji i obrazovanju. Johann von Mosheim, Istorija Crkve, str. 349.","headingId":"johan-fon-mozhajm","headingText":"Johan fon Mozhajm"},{"text":"Slučaj Zirjaba Kazivanje o Zirjabu pokazuje da su stanovnici Andaluzije sirijskog arapskog porekla svoju baštinu smatrali arapskom i neprekinutom u odnosu na sirijsku arapsku kulturu, a ne berbersku ili iberijsku. Ta veza pokazuje kako su se Sirijci u Andaluziji poistovećivali sa Arapima, produžujući istočnu arapsku civilizaciju. Jonathan Holt Shannon, Performing al Andalus, str. 76.","headingId":"slucaj-zirjaba","headingText":"Slučaj Zirjaba"}]},{"slug":"arabeska-je-arapska-umetnost","chunks":[{"text":"Biljni obrasci koji ukrašavaju palmirske skulpture i građevine odgovaraju domaćim tkanim uzorcima, što upućuje na izvorno arapsko umetničko poreklo. Palmira je bila trgovački arapski grad koji je gospodario pustinjskom trgovinom, a njena arhitektura spajala je arapske i helenističke odlike. Vorik Bol navodi da su znaci palmirske arhitekture duboko semitski, a ne puko podražavanje grčko rimskog klasicizma.","headingId":"","headingText":""},{"text":"Palmirski obrasci Biljni obrasci koji ukrašavaju palmirske skulpture i građevine podsećaju na domaće tkane uzorke, što upućuje na izvorno arapsko umetničko poreklo. Vezu između graditeljskih ukrasa i domaćih umetničkih obrazaca dokumentuje Džoan Aruz. Joan Aruz, Palmyra: Mirage in the Desert, str. 69.","headingId":"palmirski-obrasci","headingText":"Palmirski obrasci"},{"text":"Palmira kao arapski grad Palmira je bila trgovački arapski grad koji je gospodario pustinjskom trgovinom, sa graditeljskim odlikama koje spajaju arapske i helenističke elemente. Palmiru kao trgovački arapski grad koji je gospodario pustinjskom trgovinom opisuje Džemal el Halebi. Jamal Al Halabi, The Armour of Light, str. 62.","headingId":"palmira-kao-arapski-grad","headingText":"Palmira kao arapski grad"},{"text":"Semitsko poreklo Znaci palmirske arhitekture duboko su semitski, a ne puko podražavanje grčko rimskog klasicizma. Warwick Ball, Rome in the East, str. 85. Time se arabeska utvrđuje kao drevna arapska umetnička tradicija, koja prethodi islamskoj civilizaciji.","headingId":"semitsko-poreklo","headingText":"Semitsko poreklo"}]},{"slug":"arapi-i-prenos-znanja-u-Indiju","chunks":[{"text":"Arapi su doprineli prenosu nauka sa arapskog Istoka u Indiju još pre poslanstva. Samjuel Baret Majls navodi da su upravo arapski trgovci bili razlog tog prenosa i uzrok svetovnih nauka koje je Indija posedovala. Krispin Bejts navodi da je hinduistička dinastija Gupta, koja je Indijom vladala od 320. do 547. godine, imala brojne veze sa Arapima i od njih preuzela astronomske i matematičke nauke. Arapi su doprineli prenosu nauka sa arapskog Istoka u Indiju još pre poslanstva. Samjuel Baret Majls navodi da su arapski trgovci bili razlog prenosa nauka sa arapskog Istoka u Indiju i da su bili uzrok svetovnih nauka koje je Indija posedovala. Samuel Barrett Miles, The Countries and Tribes of the Persian Gulf, str. 13. Naučna razmena","headingId":"","headingText":""},{"text":"između Indije i Arapa nastavila se i kasnije. Istraživač Krispin Bejts spomenuo je da je hinduistička dinastija Gupta, koja je Indijom vladala od 320. do 547. godine, imala brojne veze sa Arapima i da je od njih preuzela astronomske i matematičke nauke, pri čemu se verovatno misli na Lahmide i Gasanide. Zahvaljujući tim arapskim naukama razvili su plovidbu i trgovinu po čitavom Indijskom okeanu. Crispin Bates, Subalterns and Raj: South Asia since 1600, str. 18.","headingId":"","headingText":""}]},{"slug":"arapi-kao-graditelji-gradova","chunks":[{"text":"Istorijske knjige Arape spominju kao graditelje i stanovnike gradova, a ne samo kao nomade. Plinije navodi da je arapski kralj Aspasin, kralj Mesene, obnovio i ponovo podigao grad Haraks. Juba navodi da je čuveni grad Heliopolis u Egiptu, današnji Ajn Šems, osnovala skupina Arapa. Istorijske knjige Arape spominju kao graditelje i stanovnike gradova, a ne samo kao nomade.","headingId":"","headingText":""},{"text":"Plinije o kralju Aspasinu Plinije spominje da je arapski kralj Aspasin, kralj Mesene, obnovio i ponovo podigao grad Haraks. Plinije Stariji, Prirodna istorija, 6.139 i 6.177.","headingId":"plinije-o-kralju-aspasinu","headingText":"Plinije o kralju Aspasinu"},{"text":"Juba o Heliopolisu Juba navodi da je čuveni grad Heliopolis, današnji Ajn Šems u Egiptu, osnovala skupina Arapa. M. C. A. Macdonald, Arabs, Arabias and Arabic before Late Antiquity, str. 284.","headingId":"juba-o-heliopolisu","headingText":"Juba o Heliopolisu"}]},{"slug":"Arapi-Levanta-i-Iraka-nazivani-Sirijcima","chunks":[{"text":"Arapi koji su se nastanili u Levantu i Iraku nazivani su sirijskim Arapima, jer se naziv Sirija izvorno odnosio i na Levant i na Irak zajedno. Strabon Arape koji žive od zapadno od Eufrata do egipatskog mora naziva Sirijcima, Pojtingerova karta oblast od Damaska do Apameje označava kao Arabia Syria, a Julija Domna Arapkinja u Historia Augusta naziva se Sirijkom.","headingId":"","headingText":""},{"text":"Uvod Arapi koji su se nastanili u Levantu i Iraku nazivani su sirijskim Arapima, jer se naziv Sirija izvorno odnosio i na Levant i na Irak zajedno, a ne na jednu zemlju bez druge.","headingId":"uvod","headingText":"Uvod"},{"text":"Strabon o arapskim Sirijcima Strabon je o svim Sirijcima koji žive od zapadno od Eufrata do egipatskog mora, dakle u Fenikiji, Palestini, Kilikiji, Edesi i tako dalje, rekao da su to Arapi koji se nazivaju Sirijcima ili Asircima. To ukazuje na to da su Arapi bili većina u Siriji i da su nazivani Sirijcima. Strabon, Geografija, 16.1.1.","headingId":"strabon-o-arapskim-sirijcima","headingText":"Strabon o arapskim Sirijcima"},{"text":"Pojtingerova karta Arabia Syria Pojtingerova karta iz drugog ili trećeg veka nove ere velik deo Levanta, koji se proteže od Damaska do Apameje, označava nazivom Arabia Syria. Tabula Peutingeriana.","headingId":"pojtingerova-karta-arabia-syria","headingText":"Pojtingerova karta - Arabia Syria"},{"text":"Julija Domna Arapkinja nazvana Sirijkom Julija Domna Arapkinja, unuka Jambliha, kralja zemlje Arapa, odnosno oblasti Homsa, u životopisu Septimija naziva se Sirijkom. Historia Augusta, Život Septimija Severa, 3:9.","headingId":"julija-domna-arapkinja-nazvana-sirijkom","headingText":"Julija Domna Arapkinja nazvana Sirijkom"},{"text":"Posidonije o arapskim plemenima Posidonije, rođen u Apameji u drugom veku pre nove ere, navodi da se Arapi sastoje od tri plemena: Armijaca, Aramejaca i Erimba. Aramejski je, međutim, jezik, a ne etnička pripadnost, a Aramejci, koji su prema Posidoniju među Arapima, nazivani su Sirijcima. Posidonije.","headingId":"posidonije-o-arapskim-plemenima","headingText":"Posidonije o arapskim plemenima"},{"text":"Zaključak Drevni grčki, rimski i kartografski izvori pokazuju da su Arapi naseljavali Levant i Irak, da su nazivani sirijskim Arapima, i da je naziv Sirijac bio jezička i geografska, a ne etnička odrednica odvojena od arapskog identiteta.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"arapi-medju-stanovnicima-Aleksandrije","chunks":[{"text":"Dion Hrizostom, u prvom veku nove ere, među stanovnicima Aleksandrije izričito navodi i Arape. To svedočanstvo dokumentuje arapsko prisustvo u Aleksandriji u starom veku, dakle pre islamskog razdoblja. Dion Hrizostom, iz prvog veka nove ere, u Aleksandriji prepoznaje više naroda: Grci, Italici, Libijci, Kilikijci, Arapi, Etiopljani, Skiti, Persijanci, Indijci. Izvor: Dion Hrizostom iz Pruse. Dion Hrizostom, Govor 32.40; Dio Chrysostom, tom 3, str. 211, Harvard. Aleksandrija je bila raznorodan grad, koji su naseljavali razni narodi, naročito Grci, Arapi, Persijanci i Rimljani. To svedočanstvo dokumentuje arapsko prisustvo u Aleksandriji u starom veku, dakle pre islamskog razdoblja.","headingId":"","headingText":""}]},{"slug":"arapi-u-Jordanu","chunks":[{"text":"Jordan je istorijski poznat po tome što je bio deo arapskih država i naroda koji su nastali u južnom Levantu, poput Kedarana, Nabatejaca i Iturejaca. Strabon Petru naziva najvećim gradom Jordana i gradom arapskih Nabatejaca. Origen Džeraš opisuje kao arapsku zemlju, a Jevsevije Kesarijski Aman naziva gradom u zemljama Arapa. Jordan je istorijski poznat po tome što je bio deo arapskih država i naroda koji su nastali u južnom Levantu, poput Kedarana, Nabatejaca i Iturejaca. Jordan se vezuje i za nabatejsku Arabiju, koja je obuhvatala južnu Siriju, Jordan i delove Palestine. Drevni izvori dokumentovali su da je Jordan deo zemalja Arapa.","headingId":"","headingText":""},{"text":"Strabon o Petri Strabon Petru spominje kao najveći grad Jordana i opisuje je kao grad arapskih Nabatejaca. Strabon, Geografija, 16.4.18.","headingId":"strabon-o-petri","headingText":"Strabon o Petri"},{"text":"Josif Flavije o reci Arnon Josif Flavije navodi da reka Arnon, današnji Vadi Mudžib, izvire iz planina Arabije. Vadi Mudžib se danas nalazi južno od grada Dibana u Madabi, u Jordanu. Josif Flavije, Jevrejske starine, 4.5.1.","headingId":"josif-flavije-o-reci-arnon","headingText":"Josif Flavije o reci Arnon"},{"text":"Origen o reci Jabok i o Džerašu Origen navodi da reka Jabok, današnja Zerka u Jordanu, pripada zemljama Arapa. Origen grad Gerasu, današnji Džeraš, opisuje kao arapsku zemlju. Origen, Komentar Jovanovog jevanđelja, 6.24.","headingId":"origen-o-reci-jabok-i-o-dzerasu","headingText":"Origen o reci Jabok i o Džerašu"},{"text":"Jevsevije Kesarijski o Amanu Aman: grad u zemljama Arapa, u naše vreme poznat kao Filadelfija. Izvor: Jevsevije Kesarijski. Jevsevije Kesarijski, Onomastikon, str. 18.","headingId":"jevsevije-kesarijski-o-amanu","headingText":"Jevsevije Kesarijski o Amanu"},{"text":"Natpis iz Bile Natpis iz jordanskog grada Bile, koji potiče iz 522. godine, vojnike iz Jordana i Bosre opisuje kao ljude iz zemlje arapskog naroda. Arab Kings, Arab Tribes, Arab Historical Memory, str. 396.","headingId":"natpis-iz-bile","headingText":"Natpis iz Bile"},{"text":"Stefan Vizantinac o Gileadu Stefan Vizantinac zemlju Gilead opisuje kao arapsku zemlju. Stephani Byzantii Ethnica, tom 1, str. 399.","headingId":"stefan-vizantinac-o-gileadu","headingText":"Stefan Vizantinac o Gileadu"}]},{"slug":"arapi-u-Palestini","chunks":[{"text":"Svedočanstva su poređana hronološki, od Herodota u petom veku pre nove ere do Prokopija u šestom veku nove ere. Strabon navodi da su Arapi rašireni po svim delovima Palestine i da su njeni stanovnici. Josif Flavije beleži da je kralj Hirkan potvrdio trinaest arapskih gradova u Palestini i Jordanu. Prokopije navodi da se zemlja od Ejle do Gaze nazivala zemljom Arapa.","headingId":"","headingText":""},{"text":"Herodot, peti vek pre nove ere Herodot više puta spominje Palestinu i navodi da su njeni stanovnici nazivani Filistejcima, pri čemu je južna Gaza potpadala pod arapsku vlast. Herodot, Istorija.","headingId":"herodot-peti-vek-pre-nove-ere","headingText":"Herodot, peti vek pre nove ere"},{"text":"Pseudo Skilaks, četvrti vek pre nove ere Obala od južne Palestine do Peluzijuma nazivana je Arapskom obalom. Pseudo Skilaks, Periplus.","headingId":"pseudo-skilaks-cetvrti-vek-pre-nove-ere","headingText":"Pseudo-Skilaks, četvrti vek pre nove ere"},{"text":"Druga knjiga dnevnika 26:7 Spominje se Gur Baal u Negevu, čiji su glavni stanovnici bili Arapi. 2. Dnevnika 26:7.","headingId":"druga-knjiga-dnevnika-267","headingText":"Druga knjiga dnevnika 26:7"},{"text":"Strabon, prvi vek nove ere Arapi su rašireni po svim delovima Palestine i njeni su stanovnici. Izvor: Strabon. Strabon, Geografija. Strabon navodi i egipatske, arapske i feničanske zajednice u Galileji, Samariji i Jerihonu, kao i Arape Edomite koji žive zapadno od Judeje.","headingId":"strabon-prvi-vek-nove-ere","headingText":"Strabon, prvi vek nove ere"},{"text":"Josif Flavije, prvi vek nove ere Josif Flavije prenosi da je Mitridat nagovorio Arape u Askalonu da mu pomognu u ratu, što svedoči o arapskom prisustvu na palestinskoj obali. Josif Flavije. Josif Flavije beleži i da je kralj Hirkan potvrdio trinaest arapskih gradova u Palestini i Jordanu, među njima Marisu i Madabu, koje su Jevreji bili uzeli od Arapa. Josif Flavije, Jevrejske starine.","headingId":"josif-flavije-prvi-vek-nove-ere","headingText":"Josif Flavije, prvi vek nove ere"},{"text":"Natpis iz Marise Sinovi Zejdovi, Kedarani, stanovnici južnih Arapa. Taj natpis ukazuje na arapsko prisustvo u južnoj i središnjoj Palestini.","headingId":"natpis-iz-marise","headingText":"Natpis iz Marise"},{"text":"Grčki natpis iz četvrtog veka Natpis za jednog Arapa iz Azarije glasi: Gospode, pomozi svome sluzi Asimu.","headingId":"grcki-natpis-iz-cetvrtog-veka","headingText":"Grčki natpis iz četvrtog veka"},{"text":"Prokopije, šesti vek nove ere Prokopije navodi da se zemlja od Ejle do Gaze nazivala zemljom Arapa. Prokopije iz Cezareje.","headingId":"prokopije-sesti-vek-nove-ere","headingText":"Prokopije, šesti vek nove ere"}]},{"slug":"arapski-identitet-Dzezire","chunks":[{"text":"Džezira, u drevnim knjigama poznata kao zemlja Arapa, uglavnom je naseljena Arapima. Plinije o zemlji Arapa Edese govori na tri mesta: prvo je omeđuje Komagenom i Eufratom, drugo je smešta između Tigra i Eufrata, a treće navodi da oblastima reke Tigar gospodare Arapi. Zaharija Ritor u šestom veku navodi da su Arapi stanovnici gornjih oblasti Mesopotamije. Džezira, koja se u drevnim knjigama naziva zemljom Arapa, uglavnom je naseljena Arapima.","headingId":"","headingText":""},{"text":"Plinijeva tri teksta Plinije je o zemlji Arapa Edese govorio na tri mesta u svom delu.","headingId":"plinijeva-tri-teksta","headingText":"Plinijeva tri teksta"},{"text":"Prvi tekst Granice zemlje Arapa Edese počinju kod Komagene, gde reka Eufrat razdvaja Komagenu od zemlje Arapa Edese. Robert Hojland primećuje da se, prema tom tekstu, zemlja Arapa Edese proteže od istočno od Eufrata do planina Taurus i Komagene. Plinije Stariji, 5.85; Robert Hoyland, Arabia and the Arabs, str. 3.","headingId":"prvi-tekst","headingText":"Prvi tekst"},{"text":"Drugi tekst Arapi Edese naseljavaju zemlju smeštenu između reka Tigar i Eufrat, koja čini početak Mesopotamije. Plinije Stariji, 6.25.","headingId":"drugi-tekst","headingText":"Drugi tekst"},{"text":"Treći tekst Navodeći Klaudija, spominje se da oblastima reke Tigar gospodare Arapi. Plinije Stariji, 6.129.","headingId":"treci-tekst","headingText":"Treći tekst"},{"text":"Zaključak iz tih tekstova Na osnovu tih tekstova može se reći da zemlja Arapa Edese počinje na granicama Komagene, kod reke Eufrat koja ih razdvaja, prema prvom tekstu, a završava se kod Adijabene, na reci Tigar koja ih razdvaja, prema drugom tekstu.","headingId":"zakljucak-iz-tih-tekstova","headingText":"Zaključak iz tih tekstova"},{"text":"Zaharija Ritor, šesti vek Zaharija Ritor navodi da su Arapi stanovnici gornjih oblasti Mesopotamije. The Chronicle of Pseudo Zachariah Rhetor: Church and War in Late Antiquity, str. 231 232, 304 305, 332.","headingId":"zaharija-ritor-sesti-vek","headingText":"Zaharija Ritor, šesti vek"}]},{"slug":"arapski-identitet-Iraka","chunks":[{"text":"Svedočanstva su poređana hronološki. Ksenofont u petom veku pre nove ere navodi da je Kir Mlađi pokorio Kapadokiju, zatim Arape, pa Vavilon. Eratosten navodi da arapska plemena žive sa obe strane Eufrata. Kasije Dion severni Irak naziva zemljom Arapa. U asirskim natpisima središnji Irak opisuje se kao zemlja Arapa, a Arapi se u severnom Iraku spominju već u asirskom tekstu iz osmog veka.","headingId":"","headingText":""},{"text":"Ksenofont, peti vek pre nove ere Ksenofont, istoričar pohoda Kira Mlađeg, o severnom i središnjem Iraku navodi da je Kir Mlađi pokorio Kapadokiju, zatim Arape, pa Vavilon. Ksenofont, Anabaza. Dodaje i da je Kir prošao kroz Siriju, potom kroz Habur, drevni Araks, pa kroz Arabiju, sa Eufratom sa svoje desne strane, sve dok nije stigao do grada Pile, današnjeg Hita. Ksenofont, Anabaza.","headingId":"ksenofont-peti-vek-pre-nove-ere","headingText":"Ksenofont, peti vek pre nove ere"},{"text":"Eratosten, treći vek pre nove ere Eratosten o Džeziri navodi da arapska plemena žive sa obe strane reke Eufrat, od severnog do južnog Iraka. Eratosten.","headingId":"eratosten-treci-vek-pre-nove-ere","headingText":"Eratosten, treći vek pre nove ere"},{"text":"Plinije Plinije spominje postojanje arapskog plemena u severnom Iraku, nazvanog Pratavi, sa prestonicom u Singari, današnjem Mosulu. Plinije Stariji, Prirodna istorija.","headingId":"plinije","headingText":"Plinije"},{"text":"Car Klaudije, prvi vek nove ere Rimski car Klaudije napisao je knjigu o reci Tigar i naveo da su istočna severna Sirija i severni Irak, odnosno Džezira, deo zemalja Arapa. Klaudije, o reci Tigar.","headingId":"car-klaudije-prvi-vek-nove-ere","headingText":"Car Klaudije, prvi vek nove ere"},{"text":"Kurcije Kurcije navodi da je nakon Aleksandrovog osvajanja grada Erbila arapska Džezira bila sa njegove leve strane. Kvint Kurcije Ruf.","headingId":"kurcije","headingText":"Kurcije"},{"text":"Kasije Dion, treći vek nove ere Kasije Dion severni Irak naziva zemljom Arapa: Otišao je na arapsko ostrvo i borio se protiv stanovnika Hatre. Izvor: Kasije Dion. Kasije Dion, Rimska istorija.","headingId":"kasije-dion-treci-vek-nove-ere","headingText":"Kasije Dion, treći vek nove ere"},{"text":"Sirijski izvori U sirijskim izvorima, Bet Arbaje, crkvena oblast koja obuhvata najveći deo severnog Iraka i delove jugoistočne Turske, opisuje se kao oblast sa arapskim stanovništvom. Na nestorijanskom saboru 497. godine, mitropolit oblasti severnog Iraka i jugoistočne Turske, sa sedištem u Nisibinu, nazvan je mitropolitom zemlje Arapa.","headingId":"sirijski-izvori","headingText":"Sirijski izvori"},{"text":"Grčki dokument iz Dura Europosa Grčki dokument iz grada Dura Europos u sirijskoj pustinji, datiran u 121. godinu, spominje arabarha, to jest vladara Arapa, u toj oblasti.","headingId":"grcki-dokument-iz-dura-europosa","headingText":"Grčki dokument iz Dura Europosa"},{"text":"Stefan Vizantinac, šesti vek Stefan Vizantinac Džeziru spominje dvaput u svom delu Ethnica. Stephani Byzantii, Ethnica.","headingId":"stefan-vizantinac-sesti-vek","headingText":"Stefan Vizantinac, šesti vek"},{"text":"Ostala svedočanstva Hrišćanski istoričar poznat kao Samani navodi da su, prema hronikama Maruta, biskupa Tikrita, Arapi ispunili Džeziru. Rimski istoričar Amijan spominje Arape koji žive u šatorima, a koje su ljudi u kasnijim razdobljima nazivali Saracenima. Naveo je i da su se granice saracenskih Arapa protezale od Asiraca, to jest od Tigra, do Nila u Egiptu. Amijan Marcelin, Res Gestae. Strabon u svojoj Geografiji navodi da su stanovnici Mejsana, zapadnih i središnjih oblasti Vavilonije, bili Arapi. Strabon, Geografija. Istoričar Zaharija Ritor, biskup Gaze, navodi da su Arapi stanovnici Mesopotamije i Gornje Džezire. Zaharija Ritor. Jedan sirijski izvor donosi životopis Mar Ahudemeha, hrišćanskog sirijskog monaha arapskog porekla, iz grada Belada u današnjem Iraku.","headingId":"ostala-svedocanstva","headingText":"Ostala svedočanstva"},{"text":"Asirski izvori 1. Arapi se u severnom Iraku spominju u asirskom tekstu iz osmog veka kao stanovnici grada Kalhua, odnosno Nimruda. 2. Središnji Irak u asirskim natpisima opisuje se kao zemlja Arapa. 3. U asirskim natpisima najveći deo oblasti Anbara svrstava se u zemlje koje naseljavaju Arapi. 4. Pisma asirskog službenika Tab sil Išare ukazuju na to da su Arapi imali snažno prisustvo u području koje se prostire od Sipara na jugu do reke Tartar na severu.","headingId":"asirski-izvori","headingText":"Asirski izvori"}]},{"slug":"arapski-identitet-Libana","chunks":[{"text":"Zemlja Fenicije, uključujući istočne i zapadne libanske planine i Bekansku dolinu, bila je arapska zemlja. Kurcije u drugom veku zapadni libanski venac opisuje kao arapsko područje, Arijan navodi da je Aleksandar krenuo ka Arabiji, ka istočnim libanskim planinama, a Isidor Seviljski te planine izričito naziva planinama Arabije.","headingId":"","headingText":""},{"text":"Uvod Ponekad se iznose tvrdnje da su pojedine skupine potomci Feničana i da su bili stanovnici Libana pre Arapa. Zemlja Fenicije, međutim, uključujući istočne i zapadne libanske planine i Bekansku dolinu, bila je arapska zemlja.","headingId":"uvod","headingText":"Uvod"},{"text":"Zapadne libanske planine Kurcije, iz drugog veka nove ere, zapadni libanski venac opisuje kao arapsko područje, navodeći da su na planini Liban zemljoradnici iz Arabije napali Makedonce. Kvint Kurcije Ruf, Istorija Aleksandra Velikog. To znači da je planina Liban i u vreme Aleksandra Velikog bila prepoznata kao arapska zemlja.","headingId":"zapadne-libanske-planine","headingText":"Zapadne libanske planine"},{"text":"Istočne libanske planine Arijan navodi: Aleksandar je sa stražom i strelcima krenuo ka Arabiji, ka istočnim libanskim planinama, da zauzme taj deo tih zemalja. Izvor: Arijan. Arijan, Anabaza Aleksandrova.","headingId":"istocne-libanske-planine","headingText":"Istočne libanske planine"},{"text":"Arapi Iturejci Iturejci su u jednom latinskom natpisu opisani kao stanovnici planine Liban, u obliku „Ituraei in Libano Monte\", to jest Iturejci na planini Libanu. Kasije Dion opisuje kako je rimski car zemlju arapskih Iturejaca dodelio Sohemu. Kasije Dion, Rimska istorija.","headingId":"arapi-iturejci","headingText":"Arapi Iturejci"},{"text":"Dodatna svedočanstva Eratosten navodi da su arapska staništa, uključujući i iturejska, planinska, i to u oblastima oko Bekanske doline. Eratosten. Isidor Seviljski navodi: Planine Arabije, koje se zovu Libanos i Antilibanos, to jest istočne i zapadne planine Libana. Izvor: Isidor Seviljski. Isidor Seviljski, Etimologije.","headingId":"dodatna-svedocanstva","headingText":"Dodatna svedočanstva"}]},{"slug":"arapski-identitet-Sirije","chunks":[{"text":"Justin u drugom veku nove ere navodi da je Damask arapska zemlja i deo zemalja Arapa. Rimljani su Feniciju Sekundu uopšteno nazivali Arabia Augusta Libanensis, to jest Kraljevska Arabija. Ciceron navodi da je Jamblih, knez Homsa, nazivan kraljem i šejhom Arapa. Plinije severnu Siriju, koja obuhvata Edesu, Samosatu i Haran, naziva zemljom Arabijom.","headingId":"","headingText":""},{"text":"Uvod Često se tvrdi da Arapi nisu ni drevni ni savremeni stanovnici arapskih zemalja, da nisu izvorni žitelji arapskog Istoka, pa čak i da su u zemljama arapskog sveta manjina, a ne većina. U nastavku se navode istorijska svedočanstva o arapskom prisustvu na sirijskim prostorima.","headingId":"uvod","headingText":"Uvod"},{"text":"Damask Justin, iz drugog veka nove ere, navodi da je Damask arapska zemlja i deo zemalja Arapa. Justin, Istorija.","headingId":"damask","headingText":"Damask"},{"text":"Središnja Sirija Rimljani su zemlju Fenicije Sekunde uopšteno nazivali Arabia Augusta Libanensis, što znači Kraljevska Arabija.","headingId":"sredisnja-sirija","headingText":"Središnja Sirija"},{"text":"Oblast Homsa Ciceron je spomenuo da je prvak porodice Šemsigram, Jamblih, knez Homsa, nazivan kraljem i šejhom Arapa. Ciceron.","headingId":"oblast-homsa","headingText":"Oblast Homsa"},{"text":"Južne oblasti Istoričar Sekst Afrikanac spomenuo je da je Antonije krunisao Iroda i predao mu upravu nad gradovima Hipos, Gadara, Gaza, Jafa i Antedon, kao i nad pojedinim gradovima na arapskom području, poput Trahona, odnosno Ledže, Haurana, Sakije i Golana. Sekst Julije Afrikanac.","headingId":"juzne-oblasti","headingText":"Južne oblasti"},{"text":"Palmira Istoričar Polibije, iz drugog veka, govori o arapskom vođi koji zapoveda sa deset hiljada boraca iz zemalja Arapa, a ime tog vođe je Zabdibel. Polibije, Istorije.","headingId":"palmira","headingText":"Palmira"},{"text":"Severne oblasti Plinije je oblast severne Sirije, koja obuhvata Edesu, Samosatu, Haran i druge gradove i oblasti, nazvao zemljom Arabijom. Plinije Stariji, Prirodna istorija.","headingId":"severne-oblasti","headingText":"Severne oblasti"}]},{"slug":"Asija-bint-Muzahim-i-Isis-Nefert","chunks":[{"text":"Poređenje između Asije bint Muzahim, faraonove žene koju Kur'an navodi kao primer vernicima, i Isis Nefert, žene Ramzesa II iz devetnaeste dinastije, pokazuje šest podudarnosti: obe su bile faraonove žene, obe nefaraonskog porekla, Isis Nefert je bila lišena punih kraljevskih naslova, javlja se jezička veza preko imena, obe su nastradale nasilnom smrću u ranim godinama, i za obe je grob do danas nepoznat.","headingId":"","headingText":""},{"text":"Ko je Asija bint Muzahim Najbolje žene među stanovnicima Dženneta jesu Hatidža bint Huvejlid, Fatima bint Muhammed, Merjema bint Imran i Asija bint Muzahim, faraonova žena. Izvor: Sahihul džami, ocenjeno verodostojnim kod Albanija. Sahihul džami, ocena Albanija. Sura Et Tahrim 66:11 A onima koji veruju, Allah kao primer navodi ženu faraonovu, kada je rekla: Gospodaru moj, sagradi mi kod Sebe kuću u Džennetu.","headingId":"ko-je-asija-bint-muzahim","headingText":"Ko je Asija bint Muzahim"},{"text":"Šta Ibn Kesir navodi o Asiji 1. Asija je bila žena faraona iz Musaovog doba. 2. Nije bila faraonskog porekla, na šta ukazuje i samo njeno ime. 3. Nastradala je nasilnom smrću, ubistvom na najstrašniji način. Ibn Kesir, El Bidaje ven nihaje.","headingId":"sta-ibn-kesir-navodi-o-asiji","headingText":"Šta Ibn Kesir navodi o Asiji"},{"text":"Šest podudarnosti 1. Položaj supruge. I Asija i Isis Nefert bile su faraonove žene. 2. Nefaraonsko poreklo. Ibn Kesir navodi da Asija nije bila faraonskog porekla, a Isis Nefert se vezuje za područje Sirije i Palestine. 3. Umanjen položaj. Isis Nefert nije imala pune kraljevske naslove koje su imale druge Ramzesove žene, poput kraljice Nefertari ili Bint Anat. Zabeležena je samo kao velika kraljevska supruga i majka kralja, dok joj upadljivo nedostaje odrednica kraljica Dve zemlje, Gornjeg i Donjeg Egipta. Jedan egiptolog primetio je: „Isis Nefert je bila isključena, a to isključenje i danas ostaje pitanje koje zbunjuje stručnjake.\" 4. Jezička veza preko imena. U Asijinom imenu javlja se odrednica bint Muzahim, a kćerka Isis Nefert nosila je ime Bint","headingId":"sest-podudarnosti","headingText":"Šest podudarnosti"},{"text":"Anat, što znači kćerka boginje Anat, paganske kanaanske boginje. 5. Nasilna smrt. Asija je ubijena pod faraonovim mučenjem. Egiptološkinja Kristijan Deroš navela je: „Isis Nefert je umrla rano, pre nego što je dosegla starost. Ubijena je i telesno uklonjena.\" Christiane Desroches Noblecourt. 6. Nepoznat grob. Mesta ukopa obe žene ostaju nepoznata do današnjeg dana.","headingId":"sest-podudarnosti","headingText":"Šest podudarnosti"},{"text":"Jezički dokaz Egipatska boginja Aset, u helenizovanom obliku Isis, jezički se povezuje sa imenom Asija preko koptskih izgovornih obrazaca, gde oblik „Aa i si\" prelazi u arapski ženski oblik imena.","headingId":"jezicki-dokaz","headingText":"Jezički dokaz"},{"text":"Odgovor na moguću primedbu Postavlja se pitanje kako se to slaže sa prikazima na kojima Isis Nefert obožava egipatska božanstva. Postoje dva objašnjenja. Prvo, da je poverovala tek nakon što je videla Musaova čuda. Drugo, da je svoju veru krila pod faraonovom tiranijom, što ima i istorijskih presedana.","headingId":"odgovor-na-mogucu-primedbu","headingText":"Odgovor na moguću primedbu"}]},{"slug":"Benu-Nadir-i-tvrdnje-orijentalista","chunks":[{"text":"Jevrejska enciklopedija tvrdi da za pohod na Benu Nadir 625. godine nije bilo zadovoljavajućeg povoda. Poznata predaja o povodu slaba je u sva tri svoja lanca: Ibn Ishak događaj nije video i rođen je 80. godine po Hidžri, Vakidi je ocenjen kao lažljivac koji izmišlja senede, a Musa ibn Ukba nije doživeo doba poslanstva. Verodostojna predaja, zabeležena kod Ebu Davuda, beleži da su Benu Nadir pristali na izdaju nakon pretećeg kurejšijskog pisma.","headingId":"","headingText":""},{"text":"Tvrdnja Jevrejska enciklopedija tvrdi da za napad na Benu Nadir 625. godine nije postojao zadovoljavajući povod.","headingId":"tvrdnja","headingText":"Tvrdnja"},{"text":"Prvo slabost poznate predaje o povodu Postoje tri lanca prenošenja te predaje, i sva tri su slaba. 1. Ibn Ishakova verzija o traženju pomoći za krvarinu nije pouzdana, jer Ibn Ishak događaj nije video, budući da je rođen 80. godine po Hidžri. 2. Vakidijev izveštaj se odbacuje, jer su učenjaci utvrdili da je bio slab lažljivac koji izmišlja lance prenošenja. Buhari je za njega rekao da mu je hadis napušten, Ahmed ibn Hanbel nazvao ga je lažljivcem, a Šafija je za njegove predaje rekao da su sve laži. 3. Predaja Musaa ibn Ukbe nema težinu, jer on događaj nije video niti je doživeo doba poslanstva.","headingId":"prvo-slabost-poznate-predaje-o-povodu","headingText":"Prvo - slabost poznate predaje o povodu"},{"text":"Drugo verodostojna predaja o izdaji Benu Nadira Verodostojna predaja, zabeležena u Sunenu Ebu Davuda, navodi da su Kurejšije zapretile Benu Nadiru da se bore protiv Poslanika ﷺ ili da snose posledice. Kada je njihovo pismo stiglo Jevrejima, Benu Nadir su pristali na izdaju. Izvor: Sunen Ebu Davud. Sunen Ebu Davud. Verodostojnost te predaje potvrdio je niz učenjaka, među njima Albani i Ibn Hadžer.","headingId":"drugo-verodostojna-predaja-o-izdaji-benu-nadira","headingText":"Drugo - verodostojna predaja o izdaji Benu Nadira"},{"text":"Tri tačke koje obaraju tvrdnju Jevrejske enciklopedije 1. Žena iz Benu Nadira obavestila je svog brata muslimana o njihovoj zaveri da ubiju Poslanika ﷺ. 2. Poslanik ﷺ im je ponudio obnavljanje ugovora, što su oni odbili. 3. Njihovo prikrivanje kurejšijskog pisma samo po sebi je ukazivalo na izdajničku nameru.","headingId":"tri-tacke-koje-obaraju-tvrdnju-jevrejske-enciklopedije","headingText":"Tri tačke koje obaraju tvrdnju Jevrejske enciklopedije"}]},{"slug":"broj-britanskih-prelazaka-na-islam","chunks":[{"text":"Prema izveštaju lista Independent, broj Britanaca koji su islam izabrali za svoju veru udvostručio se u prethodnoj deceniji. Ranije procene kretale su se između 14.000 i 25.000, dok studija centra Faith Matters procenjuje ukupno 100.000 prelazaka, uz oko 5.000 novih svake godine. To se dešava uprkos negativnoj slici islama u Britaniji.","headingId":"","headingText":""},{"text":"Izveštaj lista Independent Jedan od sveobuhvatnih pokušaja da se proceni broj ljudi koji veruju u islam u Ujedinjenom Kraljevstvu utvrdio je da se broj Britanaca koji su islam izabrali za svoju veru udvostručio u prethodnoj deceniji. Izvor: The Independent. The Independent, izveštaj o broju prelazaka na islam u Britaniji. List dalje navodi da su, nakon svetskog širenja ekstremizma, britanski muslimani bili izloženi većem preispitivanju, kritici i raščlanjivanju nego pripadnici bilo koje druge vere. Uprkos negativnoj slici islama u Britaniji, hiljade Britanaca svake godine prelazi na islam.","headingId":"izvestaj-lista-independent","headingText":"Izveštaj lista Independent"},{"text":"Poteškoća u proceni Procena broja onih koji su promenili veru u Britaniji dugo je bila otežana, jer statistike ne razlikuju da li je neko ko pripada nekoj veri u nju prešao ili je u njoj rođen.","headingId":"poteskoca-u-proceni","headingText":"Poteškoća u proceni"},{"text":"Brojke 1. Ranije procene broja onih koji su u Britaniji prešli na islam kretale su se između 14.000 i 25.000. 2. Studija centra Faith Matters procenjuje ukupno 100.000 prelazaka, uz oko 5.000 ljudi koji svake godine prelaze na islam širom zemlje. Faith Matters, studija o prelascima na islam u Britaniji.","headingId":"brojke","headingText":"Brojke"}]},{"slug":"da-li-je-Meka-postojala-pre-cetvrtog-veka","chunks":[{"text":"Tvrdnja da Meka nije postojala pre četvrtog veka nije tačna. Najstariji tekstualni zapis imena Meka potiče iz prvog veka pre nove ere, iz hasmaitskog natpisa čovek po imenu Abd Meka. Rimski geograf Klaudije Ptolemej iz Aleksandrije spominje je u drugom veku pod imenom Makoraba, a rimski istoričar Amijan Marcelin u četvrtom veku pod imenom Hijeropolis, što znači sveti grad.","headingId":"","headingText":""},{"text":"Uvod Oni koji ne veruju često tvrde da Meka nije postojala pre četvrtog veka. To, međutim, nije tačno. Kao dokaz ranijeg postojanja Meke navodi se Ptolemejeva karta iz drugog veka.","headingId":"uvod","headingText":"Uvod"},{"text":"Arheološki okvir Najpre treba imati u vidu da je Saudijska Arabija jedno od najmanje arheološki istraženih područja na čitavom Bliskom istoku. Na tu temu upućuje se i na istraživanje Hebe M. I. M. Abul Enein o predislamskoj Meki. Heba M. I. M. Aboul Enein, istraživanje o predislamskoj Meki.","headingId":"arheoloski-okvir","headingText":"Arheološki okvir"},{"text":"Meka i Kaba u drevnim istorijskim izvorima Najstarija tekstualna potvrda imena Meka potiče iz prvog veka pre nove ere, iz hasmaitskog natpisa koji je zapisao čovek po imenu Abd Meka. Lična imena poput Maki i Makijja javljaju se u safaitskim natpisima od prvog veka pre nove ere do četvrtog veka nove ere. Spominje je kao Makorabu rimski geograf Klaudije Ptolemej iz Aleksandrije u drugom veku nove ere. Spominje je i rimski istoričar Amijan Marcelin u četvrtom veku nove ere, pod imenom Hijeropolis, što znači sveti grad.","headingId":"meka-i-kaba-u-drevnim-istorijskim-izvorima","headingText":"Meka i Kaba u drevnim istorijskim izvorima"},{"text":"Svedočanstva o hodočašću Upućivanja na arapske hodočasničke običaje javljaju se u spisima svetog Epifanija, kod Nonisa, kao i u sirijskoj Huzistanskoj hronici. Sveti Epifanije; Nonis; Huzistanska hronika.","headingId":"svedocanstva-o-hodocascu","headingText":"Svedočanstva o hodočašću"}]},{"slug":"da-li-je-namaz-preuzet-od-Sumerana","chunks":[{"text":"Sumerska civilizacija nestala je u drugom milenijumu pre nove ere, više od dve hiljade godina pre Poslanika ﷺ, i bila je zaboravljena. Sumerski nalazi ostali su neotkriveni sve do devetnaestog veka, kada su Henri Rolinson i Edvard Hinks dešifrovali klinasto pismo. Nikakvo prenošenje, dakle, nije ni bilo moguće. Sličnost položaja u molitvi pre je dokaz da je Bog poslanike slao svim ranijim narodima.","headingId":"","headingText":""},{"text":"Sadržaj primedbe Tvrdi se da je poslanik Muhammed ﷺ način obavljanja namaza preuzeo od sumerske civilizacije.","headingId":"sadrzaj-primedbe","headingText":"Sadržaj primedbe"},{"text":"Prvo prenošenje nije bilo moguće Sumerska civilizacija bila je nestala i ljudi su je zaboravili stotinama godina pre pojave poslanika Muhammeda ﷺ. Sumerski nalazi ostali su neotkriveni sve do devetnaestog veka, kada su arheolozi poput Henrija Rolinsona i Edvarda Hinksa dešifrovali klinaste tekstove. Nikakvo prenošenje običaja molitve, dakle, nije ni moglo da se dogodi.","headingId":"prvo-prenosenje-nije-bilo-moguce","headingText":"Prvo - prenošenje nije bilo moguće"},{"text":"Drugo kipovi kao dokaz u prilog islamu Ti kipovi zapravo su dokaz da je Bog poslanike i izaslanike slao svim ranijim narodima. Poslanik Nuh živeo je u Mesopotamiji, a njegovi potomci molili su se tamo na isti onaj način na koji je Bog objavio njihovom pretku, poslaniku Nuhu.","headingId":"drugo-kipovi-kao-dokaz-u-prilog-islamu","headingText":"Drugo - kipovi kao dokaz u prilog islamu"},{"text":"Kako je poslanik Nuh obavljao molitvu Poslanik Nuh molio se na isti način na koji se molio poslanik Muhammed i na koji se muslimani mole i danas. Svi poslanici obavljali su molitvu na isti način, uključujući i stavljanje desne ruke preko leve.","headingId":"kako-je-poslanik-nuh-obavljao-molitvu","headingText":"Kako je poslanik Nuh obavljao molitvu"},{"text":"Zašto su Sumerani pravili te kipove Čestiti ljudi obeležavani su kipovima. Vremenom bi šejtan ljudima došaptavao i navodio ih da te kipove obožavaju kao bogove.","headingId":"zasto-su-sumerani-pravili-te-kipove","headingText":"Zašto su Sumerani pravili te kipove"},{"text":"Treće kazivanje o potopu kao dodatni dokaz Mesopotamijska kazivanja o potopu potiču od stvarnog Nuhovog potopa, s tim što su ljudi u izvorno kazivanje uneli iskrivljenja.","headingId":"trece-kazivanje-o-potopu-kao-dodatni-dokaz","headingText":"Treće - kazivanje o potopu kao dodatni dokaz"},{"text":"Četvrto molitva u vreme poslanika Ibrahima Ibrahim je u molitvi stajao, činio pregib i padao ničice, dakle isto kao u današnjem islamskom namazu.","headingId":"cetvrto-molitva-u-vreme-poslanika-ibrahima","headingText":"Četvrto - molitva u vreme poslanika Ibrahima"}]},{"slug":"da-li-se-islam-sirio-macem","chunks":[{"text":"Širenje islama počivalo je pretežno na dobrovoljnom prihvatanju, a ne na prisili. Istočni hrišćani su pre dolaska muslimana trpeli teška progonstva od vizantijskih vlasti. Savremeni hrišćanski svedoci, poput Jakova Edeskog, potvrđuju da su stanovnici prihvatali islam u velikom broju i bez ikakve prinude. Arheološki zapis islamskog osvajanja gotovo je nevidljiv, za razliku od sasanidskog razaranja koje je ostavilo masovne grobnice.","headingId":"","headingText":""},{"text":"Stanje pre osvajanja Istočni hrišćani trpeli su teška progonstva od vizantijskih vlasti pre islamskog osvajanja. Hronika iz Zukninа beleži da su rimski vladari rušili manastire i crkve i progonili sirijsko hrišćansko stanovništvo. Hronika iz Zuknina. Tomas Arnold navodi da je car Justinijan u Aleksandriji pobio oko 200.000 Kopta. T. W. Arnold, The Preaching of Islam.","headingId":"stanje-pre-osvajanja","headingText":"Stanje pre osvajanja"},{"text":"Andaluzija kao primer Islamsko osvajanje Iberijskog poluostrva predstavljalo je oslobođenje, a ne najezdu. Vil Djurant primećuje da su siromašni Jevreji i hrišćani bili ravnodušni prema padu vizigotske vlasti. Vil Djurant, Istorija civilizacije. Brajan Katlos navodi da je izvorno andaluzijsko stanovništvo dobrovoljno prihvatilo islam i postalo kulturno arapsko muslimansko. Brajan Katlos.","headingId":"andaluzija-kao-primer","headingText":"Andaluzija kao primer"},{"text":"Domaće stanovništvo kao saveznik Hrišćani u Siriji i Iraku dejstveno su pomagali muslimanske snage. Arapski hrišćani iz Homsa zatvorili su kapije pred Rimljanima, a otvorili ih pred muslimanima.","headingId":"domace-stanovnistvo-kao-saveznik","headingText":"Domaće stanovništvo kao saveznik"},{"text":"Svedočanstva savremenika Biskup Jakov Edeski, hrišćanski svedok tog doba, potvrdio je da su stanovnici prihvatali islam u velikom broju i bez ikakve prinude. Jakov Edeski. Mihailo Sirijac dolazak Arapa pripisao je božanskoj pravdi, navodeći da je Bog doveo muslimane da hrišćane izbave iz ruku Rimljana. Mihailo Sirijac, Hronika.","headingId":"svedocanstva-savremenika","headingText":"Svedočanstva savremenika"},{"text":"Arheološki nalazi Stiven Šumejker primećuje da je islamsko osvajanje u arheološkom zapisu gotovo nevidljivo, za razliku od prethodnog sasanidskog razaranja, koje je ostavilo masovne grobnice. Stephen Shoemaker.","headingId":"arheoloski-nalazi","headingText":"Arheološki nalazi"},{"text":"Ocene istoričara De Lesi O'Liri tvrdnju o širenju mačem nazvao je jednim od najbesmislenijih mitova. De Lacy O'Leary, Islam at the Crossroads. Ira Lapidus je naveo da je prisilno preobraćenje bilo retko i da je većina prelazaka na islam bila dobrovoljna. Ira Lapidus, A History of Islamic Societies. Edmon Rabat naveo je da je hrišćansko stanovništvo uopšte prihvatilo islam iz uverenja. Edmond Rabbath. Gistav le Bon naveo je da narodi nikada nisu upoznali osvajače tako snošljive kao što su bili Arapi. Gustave Le Bon, Civilizacija Arapa. Hrišćani su Omera ibn el Hattaba nazivali el Faruk, onaj koji razlikuje.","headingId":"ocene-istoricara","headingText":"Ocene istoričara"},{"text":"Pitanje džizje Sistem džizje imao je opsežna izuzeća. Nju nisu plaćale žene, starci, siromasi, monasi ni osobe sa invaliditetom. Te kategorije izričito nabraja T. W. Arnold. T. W. Arnold, The Preaching of Islam.","headingId":"pitanje-dzizje","headingText":"Pitanje džizje"},{"text":"Poređenje sa krstaškim postupanjem Kada je Omer osvojio Jerusalim, nije ubijen nijedan civil. Nasuprot tome, krstaši su 1099. godine pobili više od 40.000 žena i dece. Emil Ludvig opadanje snošljivosti pripisuje hrišćanskoj agresiji. Emil Ludwig. Patrijarh Mihailo III izričito je davao prednost muslimanskoj vlasti, navodeći da ga muslimanski vladar neće prisiljavati da prihvati njegovu veru, za razliku od franačke vlasti. Patrijarh Mihailo III.","headingId":"poredjenje-sa-krstaskim-postupanjem","headingText":"Poređenje sa krstaškim postupanjem"},{"text":"Savremeni rast Islam i danas ostaje najbrže rastuća vera na svetu, i to bez ikakve političke ili vojne moći iza sebe, što ukazuje na dobrovoljno prihvatanje, a ne na prisilno širenje.","headingId":"savremeni-rast","headingText":"Savremeni rast"}]},{"slug":"da-li-su-hriscani-prelazili-na-islam-zbog-dzizje","chunks":[{"text":"Džizja je iznosila svega dva dinara godišnje, i to samo za muškarce sposobne da nose oružje, dok se od dece, žena i staraca nije uzimala. Rimski porezi dostizali su do 12,5 odsto na raskošnu robu, a onima koji nisu mogli da plate pretili su zatvor ili porobljavanje porodice. Hrišćanski istoričari tog doba, poput Jovana Nikijskog, sami beleže dobrovoljne prelaske i pripisuju pobedu islama rimskoj nepravdi i progonu pravoslavnih.","headingId":"","headingText":""},{"text":"Hrišćanski istoričari beleže dobrovoljne prelaske Jovan Nikijski zabeležio je da su mnogi Egipćani koji su bili lažni hrišćani odbacili svetu pravoslavnu veru i prihvatili veru islama. Jovan Nikijski, Hronika. Stanovništvo se podelilo, pa su jedni podržavali muslimansku upravu, a drugi vizantijske službenike. Aleksandrija se predala mirno. Amr ibn el As ušao je bez poteškoća, a stanovnici su ga primili sa velikim poštovanjem. Papa Vениjamin, koji je trinaest godina bio u bekstvu od Rimljana, vratio se nakon osvajanja, a ljudi su pobedu islama pripisivali rimskoj nepravdi i progonu pravoslavnih.","headingId":"hriscanski-istoricari-beleze-dobrovoljne-prelaske","headingText":"Hrišćanski istoričari beleže dobrovoljne prelaske"},{"text":"Muslimani su štitili crkve i dopuštali slobodno bogosluženje Amr ibn el As nije uzeo ništa od crkvenog imetka, nije počinio nikakvu pljačku ni krađu, i crkve je čuvao sve vreme. Arheološki nalazi pokazuju neprekidne radove na crkvama, pa i nove gradnje tokom čitavog tog razdoblja. Patrijarh Išojab III žalio se da se pastva biskupa Simeona preobraća uprkos snošljivosti muslimana i njihovoj dozvoli da zadrže svoju veru. Patrijarh Išojab III, pisma. Monah Jovan ibn el Fanki zabeležio je da su muslimani svakome dopuštali da ostane u veri koju želi. Jovan ibn el Fanki.","headingId":"muslimani-su-stitili-crkve-i-dopustali-slobodno-bogosluzenje","headingText":"Muslimani su štitili crkve i dopuštali slobodno bogosluženje"},{"text":"Hrišćani su trpeli rimski progon i preteran porez Egipćani su trpeli rimski progon zbog razlika u učenju, jer su Rimljani verovali u dve Hristove prirode, a Kopti u jednu. Vizantijska vlast nametala je teške poreze, a žene i kćeri bivale su isterivane sa svoje zemlje i iz svojih domova zato što muškarci nisu mogli da plate porez. Rimski sistem obuhvatao je poreze na prihod, poreze na zemlju, izvozne i uvozne dažbine, kao i takse na sve što se kupovalo i prodavalo.","headingId":"hriscani-su-trpeli-rimski-progon-i-preteran-porez","headingText":"Hrišćani su trpeli rimski progon i preteran porez"},{"text":"Džizja u odnosu na rimski porez Džizja je iznosila svega dva dinara godišnje, i to za svakog muškarca sposobnog da nosi oružje. Od dece, žena i staraca nije se uzimala. Rimski porezi dostizali su do 12,5 odsto na raskošnu robu, a onima koji nisu mogli da plate pretili su zatvor ili porobljavanje članova porodice. Monteskje je primetio da su upravo ti preterani porezi doveli do zapanjujuće lakoće sa kojom su muslimani osvajali. Monteskje.","headingId":"dzizja-u-odnosu-na-rimski-porez","headingText":"Džizja u odnosu na rimski porez"},{"text":"Mit o Aleksandrijskoj biblioteci Priča o spaljivanju biblioteke prvi put se javlja u trinaestom veku, šest stotina godina nakon navodnog događaja, u spisima Abdul Latifa i Ebul Faradža. Nijedan savremeni izvor ne spominje razaranje biblioteke, a Jovan Nikijski, jedini istoričar koji je živeo u vreme islamskog osvajanja, nikada ga nije spomenuo.","headingId":"mit-o-aleksandrijskoj-biblioteci","headingText":"Mit o Aleksandrijskoj biblioteci"},{"text":"Zaključak Istraživač Sulejman Šafik potvrdio je da arapski muslimanski osvajači nisu vršili nikakav značajan pritisak da bi Kopte preveli na islam. Sulejman Šafik.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"da-li-su-islamska-osvajanja-bila-tlacenje","chunks":[{"text":"Egipat, arapski Magreb i Levant donosili su najveći deo vizantijskih prihoda, a njihovo stanovništvo istovremeno je trpelo verski progon i teške namete. Monofizitski hrišćani bili su surovo progonjeni i isključeni iz službi. Savremeni hrišćanski izvori, od Mihaila Sirijca do Jovana Bar Penkajea, dolazak Arapa opisuju kao olakšanje, a razdoblje njihove vladavine kao vreme pravde i blagostanja.","headingId":"","headingText":""},{"text":"Vizantija i Sasanidi Vizantijsko carstvo započelo je 330. godine pod Konstantinom I. Sredinom šestog veka držalo je Magreb, Levant, Egipat, Anadoliju, Italiju i Balkan. Sasanidska država započela je 226. godine pod Ardaširom, a njen poslednji vladar bio je Jazdegerd. Prostirala se preko Levanta i Anadolije, pa sve do granica Indije i Kine.","headingId":"vizantija-i-sasanidi","headingText":"Vizantija i Sasanidi"},{"text":"Privredno bogatstvo Egipta, Levanta i Magreba Egipat, arapski Magreb i Levant donosili su visoke prihode Vizantijskom carstvu, i najveći deo vizantijske privrede poticao je iz tih oblasti. Warren Treadgold, A History of the Byzantine State and Society, str. 402. Jermenija, Balkan i Italija bili su, u poređenju sa njima, siromašni.","headingId":"privredno-bogatstvo-egipta-levanta-i-magreba","headingText":"Privredno bogatstvo Egipta, Levanta i Magreba"},{"text":"Tlačenje podanika Uprkos svom privrednom doprinosu, stanovništvo tih oblasti trpelo je surovo tlačenje. Vizantijska vladajuća elita osiromašivala je stanovnike, i halkidonske i nehalkidonske hrišćane, dok je bogatstvo trošila na sebe. Pristalice arijanstva i monofizitstva trpele su verski progon. Halkidonski hrišćani trpeli su materijalno tlačenje, a nehalkidonski i versko i materijalno. Chris Harman, A People's History of the World, str. 119. Pristalice monofizitskog učenja bile su surovo i povremeno progonjene i isključene iz službi pod vizantijskom vlašću. Hugh Kennedy, The Great Arab Conquests, str. 67 68. Slobodni seljaci u Vizantijskom carstvu bili su porobljavani zbog verskih razlika i teških nameta. Život pod arapskom islamskom vlašću bio je daleko bolji, a nemuslimani su bili zadovoljni islamskom upravom. Roger B. Manning, War and","headingId":"tlacenje-podanika","headingText":"Tlačenje podanika"},{"text":"Peace in the Western Political Imagination, str. 89.","headingId":"tlacenje-podanika","headingText":"Tlačenje podanika"},{"text":"Nepismenost pod rimskom i sasanidskom vlašću Većina stanovnika Rimskog carstva bili su nepismeni seljaci, koji su činili 90 odsto stanovništva. Mary Cunningham, Christian Faith in the Byzantine and Medieval Worlds. Podanici Sasanidskog carstva bili su nepismeni i lišeni obrazovanja. Sasanian Empire: A Captivating Guide to the Neo Persian Empire.","headingId":"nepismenost-pod-rimskom-i-sasanidskom-vlascu","headingText":"Nepismenost pod rimskom i sasanidskom vlašću"},{"text":"Surovost hrišćanske rimske vlasti Edmon Rabat je zabeležio strahovite progone nakon Halkidonskog sabora: masovne pokolje, pojedinačna ubistva mačem i vatrom, raseljavanje stanovništva i mučenja. Edmond Rabbath, Arapski hrišćani, str. 20. Istoričar Amijan je naveo: Istorija nikada nije videla grabljivije i okrutnije zveri od hrišćana jednih prema drugima.","headingId":"surovost-hriscanske-rimske-vlasti","headingText":"Surovost hrišćanske rimske vlasti"},{"text":"Rimski zavet o istrebljenju stanovnika Levanta Teodorik, Iraklijev brat, pretio je da će ukloniti hrišćane koji se protive halkidonskom učenju. Izjavio je da je odlučan da progoni jakobite, a zatim su ga porazili muslimani. Michel le Syrien, izd. Chabot, tom 2, str. 419.","headingId":"rimski-zavet-o-istrebljenju-stanovnika-levanta","headingText":"Rimski zavet o istrebljenju stanovnika Levanta"},{"text":"Rimljani su razorili sopstvene gradove pre povlačenja Nakon poraza, Iraklije se, prema predanju, oprostio od Sirije rečima „Zbogom, Sirijo\". Njegova vojska opljačkala je sela i gradove, razorila ih i opustošila, a zatim ih ostavila muslimanima. Michel le Syrien, izd. Chabot, tom 2, str. 424.","headingId":"rimljani-su-razorili-sopstvene-gradove-pre-povlacenja","headingText":"Rimljani su razorili sopstvene gradove pre povlačenja"},{"text":"Islamsko osvajanje kao oslobođenje Jedan bagdadski sveštenik iz dvanaestog veka zabeležio je da su pre islama zoroastrijski Persijanci i hrišćanski Rimljani prema krvi hrišćana koji im se protive postupali kao prema krvi psa. Dolazak arapskih muslimana okončao je tu nepravdu i hrišćane zaštitio pod islamskom vlašću. Objašnjenje verovanja otaca Nikejskog sabora, str. 170. Mihailo Sirijac potvrdio je da su stanovnici pod rimskom vlašću živeli najgorim životom i da je Bog poslao sinove Ismailove sa juga da oslobode potlačene levantske i egipatske Arape. T. W. Arnold, The Preaching of Islam, str. 54. Jovan Bar Penkaje, koji je pisao krajem sedmog veka, naveo je za Muavijinu vladavinu: Pravda je cvetala u njegovo doba, a mir je vladao u oblastima kojima je upravljao.","headingId":"islamsko-osvajanje-kao-oslobodjenje","headingText":"Islamsko osvajanje kao oslobođenje"},{"text":"Naveo je i da nijedno doba nije upoznalo blagostanje i mir kao doba kada su vladali Arapi. John Andrew Morrow, Islam and the People of the Book, tom 1, str. 131. Arapska islamska vlast oslobodila je i arapske i nearapske narode ispod jarma Rimljana i Persijanaca, od velikog tlačenja i teške muke. Isaac Saka, The Syriacs: Faith and Civilization, tom 1, str. 193.","headingId":"islamsko-osvajanje-kao-oslobodjenje","headingText":"Islamsko osvajanje kao oslobođenje"},{"text":"Sirija pre i posle osvajanja Sirija je trpela rimsko sasanidske ratove, gladi, kuge i zemljotrese sve do islamskog osvajanja. Nakon osvajanja, Sirija je procvetala i postala važno kulturno i versko središte. Muavijina mudra i pravedna politika donela je blagostanje, a Damask je pod Emevijama postao najveći grad na svetu. Ross Burns, The Monuments of Syria: A Guide, str. 11.","headingId":"sirija-pre-i-posle-osvajanja","headingText":"Sirija pre i posle osvajanja"},{"text":"Osvajanja nisu razarala, nego su čuvala Arheološki nalazi pobijaju tvrdnju o širokom razaranju tokom osvajanja Egipta. Većina osvajanja postignuta je ugovorima i saradnjom, a imovina je bila sačuvana onakva kakva je bila i vraćena svojim vlasnicima. Roger S. Bagnall, Egypt in the Byzantine World 300 700, str. 441 442.","headingId":"osvajanja-nisu-razarala-nego-su-cuvala","headingText":"Osvajanja nisu razarala, nego su čuvala"},{"text":"Pravda, razvoj i blagostanje Osvojene zemlje doživele su pravdu, pravičnost i razvoj bez presedana u svojoj istoriji. Bliski istok video je postojanost i mir kakve nije video tokom prethodnih vekova. Poljoprivreda se razvila, a Mesopotamija je postala jedna od najbogatijih oblasti. Islamska središta široko su raširila čitanje, pisanje i znanje. Stanwood Cobb, Islamic Contributions to Civilization, 1963. Arapi su obnovili razorena imanja i sela i razvili sisteme navodnjavanja koji su povećali proizvodnju u dolinama Eufrata i Tigra. Svetska trgovina procvetala je zahvaljujući arapskim muslimanima. Arapske muslimanske vojske gradile su zemlje koje su osvajale, a nisu ih razarale, i vodili su ih pravedni vladari. Islam the Straight Path, izdanje 2005, str. 33 34.","headingId":"pravda-razvoj-i-blagostanje","headingText":"Pravda, razvoj i blagostanje"},{"text":"Arapska pismenost Arapi su imali najvišu stopu pismenosti u čitavoj staroj istoriji, bez takmaca. Sirijsko arapsko pustinjsko područje spadalo je među najpismenija područja starog sveta. M. C. A. Macdonald, Ancient North Arabian. O tome svedoče brojni safaitski i tamudski natpisi. William V. Harris, Ancient Literacy, str. 282, 1989. Gasanidski i lahmidski Arapi imali su izuzetnu pismenost i kulturnu razinu i doprineli su širenju pismenosti među Arapima Levanta i Iraka. Njihovi podanici uživali su pismenost kakvu nisu imali nearapski Anadolci, Egipćani ni Iranci pod carskom vlašću. Irfan Shahid, Byzantium and the Arabs in the Sixth Century, tom 2, deo 2, str. 295.","headingId":"arapska-pismenost","headingText":"Arapska pismenost"},{"text":"Kraj verskih sukoba Islamsko osvajanje okončalo je verske i etničke sukobe. Arapi muslimani ugasili su plamen sektaštva među hrišćanskim veroispovestima i omogućili miran suživot. Halife su raspoređivale vojnike i redare oko crkava da bi održali bezbednost i sprečili napade. Chase Robinson, The New Cambridge History of Islam, tom 1, str. 515.","headingId":"kraj-verskih-sukoba","headingText":"Kraj verskih sukoba"},{"text":"Zaključak Biskup Jakov Edeski potvrdio je da su hrišćanski stanovnici prelazili na islam u velikom broju, bez ikakvog vida prinude, batinanja ili mučenja. Sidney H. Griffith, The Church in the Shadow of the Mosque, str. 34 35.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Egipat-pre-islama","chunks":[{"text":"Antropolog Daglas Bruer dokumentuje da su u velikim gradovima ranodinastičkog razdoblja postojale pivnice koje su radile do kasno u noć, a kasniji tekstovi spominju prostitutke koje se u njima nalaze. Egiptološkinja Šarlot But navodi da je prostitucija nesumnjivo bila rasprostranjena, a da najveći deo svedočanstava o njoj potiče iz grčko rimskog razdoblja, kada je bila oporezovana i vođena evidencija. Tekst koji sledi bavi se društvenim prilikama u starom Egiptu i navodi egiptološke izvore o toj temi.","headingId":"","headingText":""},{"text":"Svedočanstvo Daglasa Bruera Antropolog Daglas Bruer dokumentuje: Kasno noćno opijanje u krčmama često je vodilo pevanju, plesu i sviranju, a muškarci i žene mogli su slobodno da opšte jedni sa drugima. Izvor: Daglas Bruer. Douglas Brewer, o društvu starog Egipta. Bruer navodi i da su krčme ostajale otvorene do kasno u noć i da su gosti pili pivo u tolikim količinama da pijanstvo nije bilo neuobičajeno. On primećuje i da su veliki gradovi ranodinastičkog razdoblja imali pivnice, a da kasniji tekstovi spominju prostitutke koje su se u njima nalazile. Poslovice koje mlade ljude opominju da se ne druže sa ženom koja nema doma upućuju na to da je prostitucija postojala u starom egipatskom društvu, možda već od kraja nakadskog razdoblja","headingId":"svedocanstvo-daglasa-bruera","headingText":"Svedočanstvo Daglasa Bruera"},{"text":"III, kada su nastala velika naselja.","headingId":"svedocanstvo-daglasa-bruera","headingText":"Svedočanstvo Daglasa Bruera"},{"text":"Svedočanstvo Šarlot But Egiptološkinja Šarlot But navodi: Kao najstariji zanat na svetu, nema sumnje da je prostitucija bila rasprostranjena. Izvor: Šarlot But. Charlotte Booth, o svakodnevnom životu u starom Egiptu. Ona navodi da su pojedine izvođačice na gozbama možda na tim okupljanjima sticale i dodatni prihod, kao i da je jedna plesačka skupina pružala usluge u zamenu za novčanu naknadu. Dodaje i da najveći deo svedočanstava o prostitutkama potiče iz grčko rimskog razdoblja, kada je prostitucija bila oporezovana i kada je o njoj vođena evidencija. But opisuje i da su mnoge prostitutke na donovima svojih sandala imale urezane pozivne poruke, poput „pođi za mnom\", koje su pri svakom koraku ostavljale otisak u blatu.","headingId":"svedocanstvo-sarlot-but","headingText":"Svedočanstvo Šarlot But"}]},{"slug":"Gasanidi","chunks":[{"text":"Gasanidi su bili veliko arapsko pleme Levanta, a najstariji pomen o njima potiče od Agatarhida sa Knida iz drugog veka pre nove ere. Bili su obrazovana dinastija, pokrovitelji nauka, umetnosti i arapske poezije, a njihovi podanici uglavnom pismeni ljudi. Zajedno sa nestorijanskim Arapima prevodili su grčka dela još pre islamskog osvajanja. Bili su i majstori navodnjavanja i hidrotehnike, čime su Levant pretvarali iz neplodne u plodnu zemlju.","headingId":"","headingText":""},{"text":"Poreklo i prvi pomeni Gasanidi su veliko i brojno arapsko pleme koje je naseljavalo Levant. Najstariji pomen o Gasanidima potiče od Agatarhida sa Knida iz drugog veka pre nove ere, kada govori o Arapima zapadne obale Arapskog poluostrva. Natpisi ukazuju na to da su Gasanidi pre svoje seobe u Levant bili u Hidžazu. Takav je natpis Harise ibn Zejda Menata, kralja, koji najverovatnije potiče iz prvog veka pre nove ere. I Strabon spominje postojanje kralja po imenu Harisa u zemlji Hidžaz. Strabon, Geografija.","headingId":"poreklo-i-prvi-pomeni","headingText":"Poreklo i prvi pomeni"},{"text":"Znanje i književnost Gasanidi su bili civilizovan narod poznat po znanju i književnosti, i ljubitelji nauka i civilizacije. Javljaju se kao obrazovana dinastija, doprinosioci suzbijanju nepismenosti, pokrovitelji nauka, umetnosti i arapske poezije. Nur Masalha, Palestine Across Millennia, str. 38. Gasanidski podanici iz arapskog Levanta bili su uglavnom obrazovani ljudi. The Jewish Apocalyptic Heritage in Early Christianity, ur. James C. VanderKam, str. 141.","headingId":"znanje-i-knjizevnost","headingText":"Znanje i književnost"},{"text":"Prevodilački rad Uticaj Gasanida ne završava se time, nego se proteže do toga da su bili predvodnici kulturnog preporoda. Arapski Gasanidi, zajedno sa nestorijanskim Arapima, odigrali su važnu ulogu pre islamskog osvajanja prevođenjem grčkih dela. A. Beeston, Arabic Literature to the End of the Umayyad Period, str. 463. Arapi hrišćani prevodili su grčka dela na sirijski još pre islamskog osvajanja, a potom i na arapski. New Dictionary of Theology, str. 58.","headingId":"prevodilacki-rad","headingText":"Prevodilački rad"},{"text":"Mir, zakon i bezbednost Irfan Šahid navodi da su Gasanidi i Herodijani, Arapi, doprineli širenju mira, zakona i bezbednosti. Njihovo unapređivanje mira i bezbednosti dovelo je do napretka arapskog Levanta i njegove kulture, a u gradovima je u njihovo doba mnogo toga izgrađeno. Irfan Shahid, Byzantium and the Arabs in the Sixth Century.","headingId":"mir-zakon-i-bezbednost","headingText":"Mir, zakon i bezbednost"},{"text":"Navodnjavanje i hidrotehnika Gasanidi su bili majstori navodnjavanja i hidrotehnike. Objedinili su umeća Himjarita i arapskih Nabatejaca u navodnjavanju i hidrotehnici, čime su postali narod vešt u razvijanju arapskog navodnjavanja. Time su unapredili Levant u svom dobu i neplodne zemlje pretvarali u plodne. Irfan Shahid, Byzantium and the Arabs in the Sixth Century, tom 2, deo 1, str. 19 20.","headingId":"navodnjavanje-i-hidrotehnika","headingText":"Navodnjavanje i hidrotehnika"},{"text":"Nakon islamskog osvajanja Nakon islamskog osvajanja, Emevije su se u velikoj meri oslanjale na Gasanide i koristile njihovo iskustvo.","headingId":"nakon-islamskog-osvajanja","headingText":"Nakon islamskog osvajanja"}]},{"slug":"gotika-i-arapska-arhitektura","chunks":[{"text":"Kristofer Ren, britanski arhitekta i graditelj katedrale Svetog Pavla, proučavao je andaluzijske i osmanske džamije i razvio takozvanu saracensku teoriju. Prema njoj, ono što danas nazivamo gotikom može se pripisati jedino Arapima, jer su Goti, kako je sam rekao, bili bliži rušenju nego građenju.","headingId":"","headingText":""},{"text":"Kristofer Ren i saracenska teorija Kristofer Ren, koji je živeo od 1632. do 1723. godine, bio je britanski arhitekta školovan u Oksfordu, koji je izveo više od osamdeset projekata, među njima i katedralu Svetog Pavla. Ren je proučavao andaluzijske i osmanske džamijske nacrte i razvio takozvanu saracensku teoriju, prema kojoj je islamska arhitektura uticala na gotski stil.","headingId":"kristofer-ren-i-saracenska-teorija","headingText":"Kristofer Ren i saracenska teorija"},{"text":"Renove reči Ovu arhitekturu sada nazivamo gotskom arhitekturom, ali Goti su bili bliži rušenju nego građenju. Izvor: Kristofer Ren. Parentalia, navedeno u: Gross, Essays on Gothic Architecture, 1802, str. 108 109. Ren je naveo da su Arapi gradili džamije i karavansaraje koristeći zaobljen graditeljski stil, sitno kamenje i stubove. Ova arhitektura, dakle gotska, može se pripisati jedino Arapima, odnosno Saracenima, ili Maurima, to jest muslimanima. Izvor: Kristofer Ren. Parentalia, navedeno u: Gross, Essays on Gothic Architecture, 1802, str. 108 109. Kao primere naveo je i određene građevine: jednu od džamija ili palata u Fesu, ili jednu od crkava u Španiji koje su podigli Mauri, poput katedrale u Burgosu. Parentalia, navedeno u: Gross, Essays on Gothic Architecture, 1802, str. 109.","headingId":"renove-reci","headingText":"Renove reči"},{"text":"Zaključak Gotska arhitektura je, prema tome, arapskog porekla, pa bi je tačnije bilo nazivati arapskom ili saracenskom nego gotskom.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"islamska-arhitektura","chunks":[{"text":"Andaluzijska arapska arhitektura potpuno je arapskog damaščanskog porekla, a zvonik Giralda smatra se jednim od njenih najlepših primera. Islamska verska arhitektura nastala je iz graditeljskih osnova arapskog porekla, a džamija Amra ibn el Asa u Kairu bila je osnov za veliki deo arhitekture džamija u islamskim zemljama do današnjeg dana. Bosvort potvrđuje da su moreskni stil i umetnost arapskog islamskog porekla.","headingId":"","headingText":""},{"text":"Andaluzijska arhitektura Andaluzijska arapska arhitektura potpuno je arapskog damaščanskog porekla, a građevina Giralda smatra se jednim od najlepših primera te arhitekture. Temelj arhitekture Granade jeste arapski islamski.","headingId":"andaluzijska-arhitektura","headingText":"Andaluzijska arhitektura"},{"text":"Islamska verska arhitektura Islamska verska arhitektura nastala je iz graditeljskih osnova arapskog porekla, a džamija Amra ibn el Asa, koja i danas postoji u Kairu, bila je osnov za veliki deo arhitekture džamija u islamskim zemljama sve do današnjeg dana.","headingId":"islamska-verska-arhitektura","headingText":"Islamska verska arhitektura"},{"text":"Moreskna umetnost Istraživač Kliford Edmund Bosvort naveo je da se naziv Maur primenjivao i na muslimane i na Berbere. Clifford Edmund Bosworth, Encyclopédie de l'Islam, tom 6, str. 839 840, Brill, 1989. Bosvort je potvrdio da su moreskni stil i umetnost arapskog islamskog porekla, i da je zelidž izumljen u islamskim zemljama ili u evropskim oblastima pod arapskim islamskim uticajem. Clifford Edmund Bosworth, Encyclopédie de l'Islam, tom 6, str. 839 840. Ibn Haldun je naveo: Civilizacija Emevija u Andaluziji prenesena je na vladare Magreba, na Almohade i Zenate, u ovom razdoblju. Izvor: Ibn Haldun. Ibn Haldun, Mukaddima, tom 1, str. 218.","headingId":"moreskna-umetnost","headingText":"Moreskna umetnost"},{"text":"Arapi Andaluzije Arapi Andaluzije jesu Arapi Levanta, a civilizacija Andaluzije jeste civilizacija Arapa Levanta. Svi Arapi u Andaluziji, raznovrsnog porekla, prihvatili su jedan jedinstven identitet, a to je bio identitet levantskih Arapa.","headingId":"arapi-andaluzije","headingText":"Arapi Andaluzije"}]},{"slug":"jevrejska-plemena-Medine","chunks":[{"text":"Medinska povelja iz 622. godine ujedinila je muslimanska i jevrejska plemena pod uzajamnom zaštitom, uz obavezu zajedničke odbrane grada i zabranu pomaganja neprijatelju. Plemena su proterana zbog uzastopnog kršenja tog ugovora, zbog pokušaja ubistva Poslanika ﷺ i zbog dogovaranja sa neprijateljem usred rata, a ne zbog svoje vere. Osim Benu Kurejza, nijedno pleme nije pobijeno, nego im je naređeno da mirno odu.","headingId":"","headingText":""},{"text":"Medinska povelja Poslanik ﷺ je 622. godine uspostavio Medinsku povelju, ugovor koji je ujedinio muslimanska i jevrejska plemena pod uzajamnom zaštitom i suživotom. Ugovor je propisivao da sva plemena moraju braniti Medinu ako bude napadnuta i da nijednom plemenu nije dozvoljeno da pomaže neprijatelja. Ibn Ishak je zabeležio da je Poslanik sklopio sporazum kojim su muslimani i Jevreji objedinjeni kao jedna zajednica, uz obavezu da se zajedno bore protiv neprijatelja i da sporove rešavaju pred Bogom i Njegovim Poslanikom. Ibn Ishak, Sira. Sporazum je jamčio pravedno postupanje, zabranu nanošenja štete jevrejskim plemenima i zabranu prisilnog prevođenja na islam.","headingId":"medinska-povelja","headingText":"Medinska povelja"},{"text":"Prvo pleme Benu Kajnuka Prema Martinu Lingsu, Benu Kajnuka svoj ugovor nisu smatrali obavezujućim i stali su na stranu idolopoklonika protiv muslimana. Martin Lings, Muhammad: His Life Based on the Earliest Sources. Jevrejski zlatar uvredio je muslimanku, iz čega je nastala tuča u kojoj je ubijen jedan musliman. To kršenje ugovora dovelo je do njihovog progonstva, uz gubitak imovine. Poslanik ﷺ naredio je njihovo progonstvo, a ne pogubljenje. Napustili su Medinu živi.","headingId":"prvo-pleme-benu-kajnuka","headingText":"Prvo pleme - Benu Kajnuka"},{"text":"Drugo pleme Benu Nadir Benu Nadir prekršili su ugovor kovanjem zavere da ubiju Poslanika ﷺ. Njihov naum je otkriven, a Poslanik ﷺ je ostao nepovređen. Poslanik ﷺ dao im je deset dana da odu, uz upozorenje da će onaj ko ostane biti pogubljen. Kada im je naređeno da odu, odbili su, oslanjajući se na obećanja podrške koja nikada nisu stigla. Nakon kratke opsade, predali su se. Poslanik ﷺ im je dozvolio da mirno odu sa svojim porodicama, da na devama ponesu žene, decu i imovinu, ali bez oružja. Benu Nadir su, dakle, proterani bez prolivanja krvi.","headingId":"drugo-pleme-benu-nadir","headingText":"Drugo pleme - Benu Nadir"},{"text":"Treće pleme Benu Kurejza Tokom Bitke na Hendeku, Benu Kurejza su se tajno dogovarali sa Kurejšijama da napadnu Medinu i Poslanika ﷺ iznutra, čime su čitavu muslimansku zajednicu doveli u opasnost u njenom najkritičnijem trenutku. Poslanik ﷺ poslao je četvoricu ashaba da provere njihov stav. Kada su ih sreli, Benu Kurejza su porekli ugovor i odbili da priznaju Poslanika ﷺ, rekavši: „Ko je Allahov Poslanik? Mi ga ne poznajemo.\" Ashabi su izvestili da su oni zvanično prekršili mirovni ugovor i izdali muslimane. Nakon opsade od dvadeset pet dana, Benu Kurejza su pristali na bezuslovnu predaju i sami zatražili da im o sudbini presudi Sa'd ibn Muaz. Sa'd je presudio da muškarci budu pogubljeni, a da se žene, deca i imovina","headingId":"trece-pleme-benu-kurejza","headingText":"Treće pleme - Benu Kurejza"},{"text":"poštede.","headingId":"trece-pleme-benu-kurejza","headingText":"Treće pleme - Benu Kurejza"},{"text":"Da li je kazna bila prestroga? V. Montgomeri Vat naveo je da sudbina Benu Kurejza nije bila ni neuobičajena ni krajnja, nego uobičajena arapska praksa u slučaju ratne izdaje. W. Montgomery Watt. Martin Lings je primetio da ta kazna nije bila po islamskom zakonu, nego po jevrejskom zakonu, kako je izložen u Ponovljenom zakonu 20:12. Martin Lings. Benu Kurejza su, dakle, sami izabrali svog sudiju, a on im je presudio po njihovom sopstvenom Pismu.","headingId":"da-li-je-kazna-bila-prestroga","headingText":"Da li je kazna bila prestroga?"},{"text":"Zaključak Jevrejska plemena kažnjena su zbog uzastopnog kršenja mirovnih ugovora, zbog otvorenog neprijateljstva, zbog pokušaja ubistva i zbog dogovaranja sa neprijateljem usred rata, a ne zbog toga što su bili Jevreji. Osim Benu Kurejza, Poslanik ﷺ nijedno pleme nije pobio, nego im je naredio da mirno odu.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Jovan-Nikijski-i-osvajanje-Egipta","chunks":[{"text":"Izvorni koptski rukopis Jovana Nikijskog je izgubljen, a delo je do nas došlo kroz niz prevoda: sa koptskog na arapski, pa 1602. godine na etiopski, i tek potom na evropske jezike. Alfred Batler priznaje da je rukopis na mestima iskvaren i da sadrži mnogo grešaka. Uz to, sam Jovan Nikijski učestvovao je u jednom od poznatih krivotvorenja crkvenih dokumenata. Lepo postupajte prema stanovnicima Egipta. Izvor: verodostojan hadis Poslanika ﷺ.","headingId":"","headingText":""},{"text":"Verodostojnost biskupa Jovana Nikijskog Jovan Nikijski bio je biskup nikijske eparhije u drugoj polovini sedmog veka. On je učestvovao u jednom od krivotvorenja i falsifikovanja zabeleženih u većini knjiga koptske istorije, a koje se ticalo nasleđivanja crkvenog vodstva.","headingId":"verodostojnost-biskupa-jovana-nikijskog","headingText":"Verodostojnost biskupa Jovana Nikijskog"},{"text":"Problemi sa samim tekstom Izvorni koptski rukopis je izgubljen. Alfred Batler je priznao: Postoje mesta na kojima je prepis rukopisa iskvaren, a sadrži i mnogo grešaka. Izvor: Alfred Batler. Alfred J. Butler, The Arab Conquest of Egypt, str. 51. Delo je prošlo kroz više prevoda: sa koptskog na arapski, zatim 1602. godine na etiopski, a tek potom na evropske jezike. Svaki od tih prelaza otvarao je prostor za iskrivljenja.","headingId":"problemi-sa-samim-tekstom","headingText":"Problemi sa samim tekstom"},{"text":"Protivdokazi iz hrišćanskih izvora Otac Mansi Johanna u svojoj Istoriji koptske crkve beleži kako je Amr ibn el As postupao prema Koptima, navodeći da im je vratio sve njihove crkve koje su Rimljani bili prisvojili. Mansi Johanna, Istorija koptske crkve.","headingId":"protivdokazi-iz-hriscanskih-izvora","headingText":"Protivdokazi iz hrišćanskih izvora"}]},{"slug":"kako-je-islam-stigao-na-Maldive","chunks":[{"text":"Ibn Batuta beleži kazivanje o prelasku Maldiva na islam. U predislamsko doba mesečno bi se pojavljivalo svetleće priviđenje, koje su stanovnici tumačili kao zlog duha, pa su u primorskom hramu prinosili ljudske žrtve. Musliman po imenu Ebul Berekat dobrovoljno se ponudio, proveo noć u hramu učeći Kur'an i preživeo. Vladar i narod potom su primili islam. Ibn Batuta zabeležio je kazivanje o tome kako su Maldivi primili islam. U predislamsko doba jednom mesečno pojavljivalo bi se svetleće priviđenje, koje su stanovnici tumačili kao zlog duha. U primorskom hramu prinosili su ljudske žrtve, a svakog jutra zaticali bi žrtvu mrtvu. Musliman po imenu Ebul Berekat dobrovoljno se ponudio kao žrtva. Unutar hrama učio je kur'anske ajete i preživeo noć. Nakon toga","headingId":"","headingText":""},{"text":"su vladar i narod primili islam. Time se promenio i sam običaj: kada bi se nešto ugledalo na moru, umesto obrednog žrtvovanja pristupalo se učenju Kur'ana. Ibn Batuta, Putopis.","headingId":"","headingText":""}]},{"slug":"kako-su-muslimani-postupali-prema-hriscanima","chunks":[{"text":"Sirijski hrišćanski izvori iz sedmog veka dolazak muslimana opisuju kao izbavljenje od vizantijskog i persijskog tlačenja. Omer ibn el Hattab je 639. godine sa biskupom Gavrilom iz Kartmina sklopio ugovor kojim su sveštenstvu odobrena poreska oslobođenja, manastirima zaštita, a hrišćanima dozvola da zadrže svoje običaje. Jovan Bar Penkaje za Muavijinu vladavinu navodi da je uspostavio pravdu i mir kakve niko nije mogao ni zamisliti.","headingId":"","headingText":""},{"text":"Hrišćani koji su muslimansku vlast nazvali izbavljenjem Bog je pobedu stavio u muslimanske ruke i uklonio vizantijsko i persijsko tlačenje. Izvor: Jovan Bar Penkaje, Riš Melle, knjiga XIV. Sebastian Brock, Studies in Syriac Christianity, str. 57. Mihailo Stariji je opisao kako je vizantijski progon izazvao božansku intervenciju, navodeći da je Bog poslao arapske muslimane sa juga da hrišćane izbave od rimske okrutnosti. Jean Baptiste Chabot, Chronique de Michel le Syrien, tom 2, str. 412 413.","headingId":"hriscani-koji-su-muslimansku-vlast-nazvali-izbavljenjem","headingText":"Hrišćani koji su muslimansku vlast nazvali izbavljenjem"},{"text":"Omerov ugovor sa biskupom Gavrilom iz Kartmina Godine 639. biskup Gavrilo iz Kartmina pregovarao je sa Omerom ibn el Hattabom i izdejstvovao poreska oslobođenja za sveštenstvo, zaštitu manastira i dozvolu da hrišćani zadrže svoje običaje. Muslimani su, pod vođstvom ljudi poput Omera, prema hrišćanskim zajednicama postupali pravedno i milostivo. Izvor: Andrew Palmer. Andrew Palmer, Monk and Mason on the Tigris Frontier, str. LXII. Saradnja Mar Gavrila sa Arapima donela je verske slobode, poreska oslobođenja za sveštenstvo i zaštitu sirijskih pravoslavnih hrišćana. Izvor: Sebastian Brock. Sebastian Brock, Studies in Syriac Christianity, str. 57.","headingId":"omerov-ugovor-sa-biskupom-gavrilom-iz-kartmina","headingText":"Omerov ugovor sa biskupom Gavrilom iz Kartmina"},{"text":"Pravda i mir Muavijine vladavine Uspostavio je toliku pravdu i mir da to niko nije mogao ni zamisliti. Izvor: Jovan Bar Penkaje, Riš Melle, knjiga XV. Sebastian Brock, Studies in Syriac Christianity, str. 61. Bar Penkaje je zabeležio i da je Muavija ljudima dopuštao da slobodno žive po svojoj veri, tražeći zauzvrat jedino danak.","headingId":"pravda-i-mir-muavijine-vladavine","headingText":"Pravda i mir Muavijine vladavine"}]},{"slug":"ko-je-unistio-aleksandrijsku-biblioteku","chunks":[{"text":"Optužba da su Amr ibn el As i halifa Omer spalili Aleksandrijsku biblioteku istorijski je neutemeljena. Ona se prvi put javlja oko šest vekova nakon navodnog događaja, kod Abdul Latifa el Bagdadija. Dokumentovano razaranje jeste ono koje je 391. godine počinio aleksandrijski patrijarh Teofil nad Serapeumom, a to beleže i sami crkveni izvori. Priču odbacuju Džordž Sarton, Bernard Luis i Vil Djurant.","headingId":"","headingText":""},{"text":"Hronološki problem Prvi koji je spomenuo optužbu da je Amr ibn el As spalio biblioteku bio je Abdul Latif el Bagdadi, i to šest vekova nakon navodnog događaja, u svom delu El Ifada vel i'tibar. Optužba se, dakle, javlja tek nakon šest vekova, bez ijednog savremenog izvora koji bi je potvrdio.","headingId":"hronoloski-problem","headingText":"Hronološki problem"},{"text":"Ranije razaranje Pravoslavni hrišćani su, u razdoblju svog progona pagana, njih ubijali, rušili i uništavali faraonske starine, razbijali njihove kipove i palili njihove biblioteke. Dokumentovano razaranje jeste ono koje je 391. godine počinio Teofil, aleksandrijski patrijarh, nad Serapeumom. Taj postupak zabeležen je i u samim crkvenim izvorima.","headingId":"ranije-razaranje","headingText":"Ranije razaranje"},{"text":"Ocene istoričara Priču o tome da su biblioteku spalili muslimani odbacuju Džordž Sarton, Bernard Luis i Vil Djurant. Bernard Luis tu priču ocenjuje kao neutemeljenu i navodi da se proširila dugo nakon samog događaja. Bernard Lewis.","headingId":"ocene-istoricara","headingText":"Ocene istoričara"},{"text":"Rusoova primedba Žan Žak Ruso je primetio da bi patrijarh, da je do toga došlo, biblioteku spalio i time se još i hvalio. Žan Žak Ruso.","headingId":"rusoova-primedba","headingText":"Rusoova primedba"}]},{"slug":"koptski-ne-znaci-egipatski","chunks":[{"text":"Naziv Kopti odnosi se isključivo na pravoslavne hrišćane Egipta, a koptski jezik je narečje nastalo iz grčkog jezika. Teodor Valsamon, pravoslavni pravnik i tumač sabornih kanona iz dvanaestog veka, navodi da je koptski iskvareno i odstupajuće grčko narečje. To znači da je koptski jezik grčki, a ne staroegipatski. Naziv Kopti primenjuje se isključivo na pravoslavne hrišćane Egipta, a koptski jezik je narečje nastalo iz krila grčkog jezika. Teodor Valsamon, pravoslavni hrišćanski pravnik i tumač kanona hrišćanskih sabora iz dvanaestog veka, navodi: Koptski je iskvareno i odstupajuće grčko narečje. Izvor: Teodor Valsamon. Patrologia Graeca, tom 137, str. 249. To znači da je koptski jezik grčki, a ne staroegipatski. Muslimani u Egiptu su Egipćani, a ne Kopti.","headingId":"","headingText":""}]},{"slug":"krst-na-novcu-u-Muavijino-doba","chunks":[{"text":"Na muslimanskom novcu tog doba nisu se nalazili samo znaci krsta, nego i znaci vatre vezani za zoroastrijsku civilizaciju. Razlog su bili trgovinski odnosi islamske države, a njihovo naglo napuštanje bilo bi rizično. Zato je promena bila postepena, sve dok se sedamdesetih godina prvog veka po Hidžri nije pojavila nova vrsta novca, sa likom Abdul Melika ibn Mervana. Ovo je odgovor onima koji napadaju Muaviju ibn Ebu Sufjana, radijallahu anhu, koristeći primedbu o krstu na muslimanskom novcu njegovog doba.","headingId":"","headingText":""},{"text":"Prvo Na tom novcu nisu se nalazili samo znaci krsta, nego i znaci vatre vezani za zoroastrijsku civilizaciju. To samo po sebi pokazuje da nije bilo reči o verskom opredeljenju, jer bi u protivnom ista država istovremeno iskazivala i hrišćansko i zoroastrijsko obeležje.","headingId":"prvo","headingText":"Prvo"},{"text":"Drugo Razlog su bili trgovinski odnosi islamske države, a njihovo naglo i istovremeno napuštanje bilo bi rizično. Otuda postepenost, sve dok se sedamdesetih godina prvog veka po Hidžri, prema Timu Velsu, nije pojavila nova vrsta novca, sa likom Abdul Melika ibn Mervana. Tim Wels, o razvoju ranog islamskog novca.","headingId":"drugo","headingText":"Drugo"}]},{"slug":"mit-da-su-ucenjaci-islamske-civilizacije-bili-nearapi","chunks":[{"text":"Broj Arapa koji su učestvovali u osvajanjima bio je oko 250.000, a najviše 300.000, dok je osvojeno stanovništvo brojalo oko 30 miliona, što daje odnos jedan prema sto. Uprkos tome, studije pokazuju da su Arapi u prvom veku nakon islama činili 90 odsto muslimanskih naučnika, a kroz četiri veka 51 odsto svih učenjaka. Među prenosiocima hadisa u šest zbirki Arapi čine 54 odsto.","headingId":"","headingText":""},{"text":"Odnos stanovništva Broj Arapa koji su učestvovali u osvajanjima bio je oko 250.000, a najviše 300.000. Osvojeno stanovništvo brojalo je oko 30 miliona, što daje odnos jedan prema sto. Udeo muslimana u osvojenim zemljama nije prelazio deset odsto do kraja emevijskog razdoblja. Već i sam taj odnos pokazuje koliko je tvrdnja neodrživa. Čak i kada bi svi gradski Arapi bili učenjaci, a od nearapa samo jedan odsto obrazovan, brojnije stanovništvo bi ipak dalo više učenjaka. Ako se, dakle, pokaže da su Arapi ipak bili većina među učenjacima, to je utoliko značajnije.","headingId":"odnos-stanovnistva","headingText":"Odnos stanovništva"},{"text":"Poreklo tvrdnje Kao izvori tog prikaza navode se šuubijski pokret i evropski orijentalisti.","headingId":"poreklo-tvrdnje","headingText":"Poreklo tvrdnje"},{"text":"Šta pokazuju istraživanja 1. Jedna studija utvrdila je da je 90 odsto muslimanskih naučnika u prvih sto godina nakon islama bilo čistih Arapa. 2. Tokom četiri veka nakon islama, arapski učenjaci činili su 51 odsto ukupnog broja učenjaka, naspram 49 odsto svih ostalih naroda zajedno. 3. Druga studija, na nasumičnom uzorku, pokazala je da su arapski naučnici i do kraja trećeg veka činili većinu, 63 odsto.","headingId":"sta-pokazuju-istrazivanja","headingText":"Šta pokazuju istraživanja"},{"text":"Prenosioci hadisa Većina prenosilaca hadisa, njih 54 odsto, u šest kanonskih hadiskih zbirki bili su Arapi. Arapi su činili većinu prenosilaca u svim hadiskim knjigama, osim u Sunenu Ibn Madže, i to sa malom razlikom od četiri odsto.","headingId":"prenosioci-hadisa","headingText":"Prenosioci hadisa"},{"text":"Projekat o učenjacima Istraživači su zaključili da mevalije brojčano nisu nadmašile Arape tokom 400 godina nakon islama ni u jednoj islamskoj zemlji, osim u severnoj Africi. Arapski učenjaci nadmašivali su nearapske u velikim islamskim gradovima, uz različite odnose po oblastima.","headingId":"projekat-o-ucenjacima","headingText":"Projekat o učenjacima"},{"text":"Da li su osvojeni narodi bili obrazovaniji? Osvojene civilizacije bile su izumrle i nestale više od hiljadu godina pre osvajanja. Stopa pismenosti u Rimskom carstvu kretala se najviše između 20 i 30 odsto, i bila je ograničena na muškarce iz višeg sloja. Pod persijskom vlašću čitanje i pisanje bili su ograničeni na vladajući sloj, dok su seljaci činili većinu stanovništva.","headingId":"da-li-su-osvojeni-narodi-bili-obrazovaniji","headingText":"Da li su osvojeni narodi bili obrazovaniji?"},{"text":"Arapsko društvo pre islama Arapsko društvo sedmog veka bilo je učeno društvo sa dugom istorijom poznavanja pisma. Arapsko poluostrvo imalo je najvišu stopu pismenosti u drevnoj ljudskoj istoriji. Arapi se opisuju kao kulturno ostrvo okruženo morem nepismenih naroda, i to i unutar rimskog i persijskog carstva.","headingId":"arapsko-drustvo-pre-islama","headingText":"Arapsko društvo pre islama"},{"text":"Zaključak Islamska civilizacija izgrađena je na plećima Arapa, a zatim onih koji su od njih učili i pisali na arapskom jeziku.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"muslimanke-ucenjaci","chunks":[{"text":"Muslimanka je u islamskoj naučnoj zajednici učila i podučavala, putovala u potrazi za znanjem, pisala dela, izdavala fetve i bila pitana za savet u javnim pitanjima. Ibn Hadžer u Takribut tehzibu navodi imena 824 žene poznate po prenošenju hadisa do početka trećeg veka po Hidžri, a Sehavi u svojoj enciklopediji beleži više od 1070 životopisa istaknutih žena samo jednog veka.","headingId":"","headingText":""},{"text":"Od prvih dana islama Žene su bile prisutne u društvu od prvog trenutka pojave islama. Hatidža bint Huvejlid, radijallahu anha, prva je poverovala Poslaniku ﷺ i bila je utočište i čvrsta tvrđava islamskog poziva sve do svoje smrti desete godine poslanstva, koju je Poslanik ﷺ nazvao godinom tuge. Žene su bile i prve koje su se žrtvovale na Allahovom putu. Sumejja bint Hajjat, radijallahu anha, bila je prva šehida u islamu. Žene su bile i prve koje su se iselile radi Allaha. Rukajja bint Muhammed ﷺ prva je izbegla sa svojim mužem Osmanom ibn Affanom, radijallahu anhu. Davanje muslimanke nije se, međutim, ograničilo samo na veru, hidžru i žrtvu, nego se protegnulo i na naučno i obrazovno polje. Tako su","headingId":"od-prvih-dana-islama","headingText":"Od prvih dana islama"},{"text":"se pojavile pravnica, hadiskinja i muftija, kojima su tragaoci za znanjem dolazili, od kojih su i pojedini prvaci učenjaka uzimali znanje, i koje su pitane za fetve u pitanjima od opšteg značaja.","headingId":"od-prvih-dana-islama","headingText":"Od prvih dana islama"},{"text":"Sobe kao svetionici U ranim danima islama, majke vernika i niz velikih ashabijki bile su predvodnice ženskog naučnog pokreta. Sobe pojedinih majki vernika bile su svetionici naučnog, kulturnog i književnog zračenja.","headingId":"sobe-kao-svetionici","headingText":"Sobe kao svetionici"},{"text":"Aiša, radijallahu anha Aiša je bila na samom vrhu. Bila je rečita i poznavala je rodoslovlje i poeziju, a Poslanik ﷺ je slušao pojedine stihove koje je ona kazivala. U prenošenju hadisa bila je među najplodnijim prenosiocima i zauzima treće mesto po broju prenesenih predaja, sa oko 2210 hadisa. Pojedini tragovi navode da je Aiša imala polovinu znanja, pa je zato bila odredište pravnika među ashabima kada bi im pojedina naučna i pravna pitanja bila teška, naročito u vezi sa životom Poslanika ﷺ. Aiša je one koji su je pitali podsticala da se ne stide da postave svoje pitanje, govoreći im: „Pitajte, jer ja sam vaša majka.\" Znanje je od nje uzelo oko 299 ashaba i tabiina, među njima 67","headingId":"aisa-radijallahu-anha","headingText":"Aiša, radijallahu anha"},{"text":"žena.","headingId":"aisa-radijallahu-anha","headingText":"Aiša, radijallahu anha"},{"text":"Umm Selema, radijallahu anha Zehebi ju je opisao kao jednu od pravnica među ashabijkama i kao jednu od onih koje su prenele mnogo hadisa od Poslanika ﷺ. Od nje je prenosilo oko 101 ashaba i tabiina, među njima 23 žene.","headingId":"umm-selema-radijallahu-anha","headingText":"Umm Selema, radijallahu anha"},{"text":"Druge ashabijke Imena ashabijki i tabiinki poznatih po znanju i brojnim predajama mnogobrojna su, poput Esme bint Ebu Bekr es Siddik, Esme bint Umejs, Džuvejrije bint el Haris, Hafse bint Omer i Zejnebe bint Džahš, radijallahu anhunne.","headingId":"druge-ashabijke","headingText":"Druge ashabijke"},{"text":"Šta beleže pisci biografskih zbirki Muhammed ibn Sa'd spomenuo je mnoge ashabijke i tabiinke u svom delu Et Tabekatul kubra. Ibn el Esir je čitav odeljak posvetio ženama u svom delu Usdul gaba. Ibn Hadžer el Askalani u delu Takribut tehzib naveo je imena 824 žene poznate po prenošenju hadisa do početka trećeg veka po Hidžri. Ibn Hadžer el Askalani, Takribut tehzib.","headingId":"sta-beleze-pisci-biografskih-zbirki","headingText":"Šta beleže pisci biografskih zbirki"},{"text":"Učene žene kroz vekove 1. Tahira bint Ahmed ibn Jusuf et Tenuhijja , umrla 436. godine po Hidžri, pravnica i hadiskinja od koje je slušao Hatib el Bagdadi, pisac Istorije Bagdada. 2. Emetul Vahid bint el Husejn ibn Ismail , umrla 377. godine, jedna od najučenijih u šafijskom mezhebu, poznavalac nasledstva, računa i gramatike. Izdavala je fetve i o njoj su pisani hadisi. 3. Dželila bint Ali ibn el Hasan eš Šedžeri , iz petog veka po Hidžri, putovala je u potrazi za hadisima po Iraku i Levantu. Od nje su slušali pojedini veliki učenjaci, poput Sem'anija. Podučavala je decu Kur'anu. 4. Zejneb bint Meki ibn Ali ibn Kamil el Harrani , umrla 688. godine, čitav život provela je u","headingId":"ucene-zene-kroz-vekove","headingText":"Učene žene kroz vekove"},{"text":"traganju za hadisima. Učenici su se tiskali pred njenom kućom u podnožju Kasijuna u Damasku, slušali od nje hadise i pred njom čitali mnoge knjige. 5. Zejneb bint Jahja ibn el Izz ibn Abdus Selam , umrla 735. godine, bila je jedinstvena u prenošenju Malog rečnika neprekidnim slušanjem. Zehebi je o njoj rekao da je bila dobra, pobožna i da je toliko volela predaju da su joj na dan smrti pročitani brojni delovi. 6. Zejneb bint Ahmed ibn Omer ed Dimeškijja , umrla 722. godine, istaknuta prenositeljka hadisa sa senedom, kojoj su mnogi učenici putovali.","headingId":"ucene-zene-kroz-vekove","headingText":"Učene žene kroz vekove"},{"text":"Svedočanstvo Ibn Batute Veliki putopisac Ibn Batuta pripoveda da je tokom svog putovanja posetio Emevijsku džamiju u Damasku i slušao od više prenositeljki tog doba. Među njima je Zejneb bint Ahmed ibn Abdur Rahim , žena čvrstog koraka u znanju i hadisu, kao i Aiša bint Muhammed ibn el Muslim el Harranijja , koja je u džamiji držala naučni skup, a izdržavala se šivenjem. Ibn Batuta je pred njom pročitao više knjiga.","headingId":"svedocanstvo-ibn-batute","headingText":"Svedočanstvo Ibn Batute"},{"text":"Idžaze velikim učenjacima Pojedine hadiskinje bile su jedinstvene u nekim predajama, poput Zejnebe bint Sulejman ibn Ibrahim , umrle 705. godine, od koje je znanje uzeo Takijudin es Subki. Pojedine hadiskinje davale su idžazu i nizu velikih učenjaka. Zejneb bint Abdullah ibn Abdul Halim ibn Tejmijje , umrla 725. godine, dala je idžazu Ibn Hadžeru el Askalaniju. Ibn Hadžer je prenosio i od Aiše bint Muhammed ibn Abdul Hadi , koja je imala snažan sened u hadisu i od koje su mnogi prenosili. Ona je prenosila od dve hadiskinje: Sitt el Fukaha bint el Vasiti i Zejnebe bint el Kemal . Ibn Hadžer je u svom delu El Mu'džemul muessis spomenuo mnoge svoje učiteljice od kojih je uzimao znanje. Imam","headingId":"idzaze-velikim-ucenjacima","headingText":"Idžaze velikim učenjacima"},{"text":"Zehebi spomenuo je mnoge svoje učiteljice u delu Mu'džem šujuhiz Zehebi, i za pojedine je govorio: „Preselila je naša učiteljica.\"","headingId":"idzaze-velikim-ucenjacima","headingText":"Idžaze velikim učenjacima"},{"text":"Ibn Hazm o svom odgoju Žene su odigrale istaknutu ulogu u obrazovanju i odgoju velikog pravnika Ibn Hazma el Endelusija, jer su ga podučile Kur'anu, čitanju, pisanju i poeziji. Odgojen sam pod brigom žena i odrastao sam u njihovim rukama. Nisam poznavao nikoga osim njih i nisam sedeo sa muškarcima osim kada sam bio u mladosti. Podučile su me Kur'anu, kazivale mi mnoge stihove i uvežbale me u kaligrafiji. Izvor: Ibn Hazm el Endelusi. Ibn Hazm el Endelusi.","headingId":"ibn-hazm-o-svom-odgoju","headingText":"Ibn Hazm o svom odgoju"},{"text":"Fatima es Samarkandi Ugledna učenjakinja Fatima bint Muhammed ibn Ahmed es Samarkandi zauzela je visok položaj u fikhu i fetvi, prednjačila je u podučavanju i napisala niz dela. Pravedni vladar Nurudin Mahmud savetovao se sa njom u pojedinim unutrašnjim državnim pitanjima i pitao je o pojedinim pravnim pitanjima. Njen muž, veliki pravnik el Kasani, pisac dela El Bedai, ponekad bi zalutao u fetvi, pa bi ga ona vratila na ispravno i ukazala mu na grešku, a on bi se vraćao njenim rečima. Ona je izdavala fetve, a njen muž je njenu fetvu poštovao. Fetva je izlazila sa njenim potpisom i potpisima njenog oca i muža, a nakon očeve smrti fetvu su potpisivali ona i njen muž.","headingId":"fatima-es-samarkandi","headingText":"Fatima es-Samarkandi"},{"text":"Sehavijeva enciklopedija Sehavi je u svojoj velikoj enciklopediji Ed Davul lami li ehlil karnit tasi naveo više od 1070 životopisa istaknutih žena tog veka, od kojih su većina bile hadiskinje i pravnice. Es Sehavi, Ed Davul lami li ehlil karnit tasi.","headingId":"sehavijeva-enciklopedija","headingText":"Sehavijeva enciklopedija"},{"text":"Sujutijeve učiteljice Njegove učiteljice odigrale su istaknutu ulogu u njegovom naučnom oblikovanju. Učio je pred Umm Hani bint el Horini , koju je nazivao musnidom. Bila je poznavalac gramatike, a njen životopis uvrstio je u svoje delo Bugjetul vuat. Učio je i pred Umm el Fadl bint Muhammed el Makdisi, Hatidžom bint Ebul Hasan el Mukan, Nešvan bint Abdullah el Kinani, Hadžer bint Muhammed el Misrijja, Emetul Halik bint Abdul Latif el Ukabi i mnogim drugima.","headingId":"sujutijeve-uciteljice","headingText":"Sujutijeve učiteljice"},{"text":"Aiša el Baunijja To razdoblje videlo je i veliku učenjakinju i književnicu Aišu el Baunijju, jednu od najistaknutijih sufija i pesnikinja, koja je sa književnicima svog doba razmenjivala sufijske stihove. Gazi ju je u svom delu El Kevakibus saira opisao rečima: Ona je damaščanska učenjakinja i praktičar sufizma, jedna od jedinstvenih tog doba i retkosti tog vremena, po vrlini, znanju, književnosti, poeziji, veri i čestitosti. Izvor: Gazi. El Gazzi, El Kevakibus saira fi ahbaril mieteil ašira. Imala je znatan broj sufijskih dela, zbirki i pesama.","headingId":"aisa-el-baunijja","headingText":"Aiša el-Baunijja"},{"text":"Žene na čelu ustanova Pojedine učenjakinje preuzimale su položaj upraviteljki ribata, poput Zejnul Arab bint Abdur Rahman ibn Omer , umrle 704. godine, koja je preuzela položaj upraviteljke Saklatunijevog ribata, a zatim i ribata Harema.","headingId":"zene-na-celu-ustanova","headingText":"Žene na čelu ustanova"},{"text":"Znanje u vreme progona Kada su tvrđave islama pale u Andaluziji i kada su muslimani bili prisiljavani da pređu na hrišćanstvo, a inkvizicija sprovodila najteže vidove mučenja, pojedini su bili prisiljeni da javno pokažu prelazak, a islam kriju. Uprkos tim ograničenjima, muslimani su tamo nastavili svoju naučnu delatnost, a dve žene predstavljale su najviši autoritet za muslimane u šerijatskim naukama. To su bile Muslima Abda i Muslima Abla , a kod njih je učio moriskijski pravnik Abiralo, koji je napisao mnoge knjige tefsira i sunneta na aljamijado pismu koje su muslimani tamo osmislili.","headingId":"znanje-u-vreme-progona","headingText":"Znanje u vreme progona"},{"text":"Zaključak Muslimanka je imala istaknuto prisustvo u islamskoj naučnoj zajednici. Učila je, podučavala i putovala u potrazi za znanjem. Učenici su joj dolazili da od nje uzimaju znanje. Pisala je dela, izdavala fetve i bila pitana za savet u javnim pitanjima.","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"nabatejska-civilizacija","chunks":[{"text":"Nabatejci su levantski arapski narod, a najstariji njihov pomen potiče iz 312. godine pre nove ere. Bili su majstori navodnjavanja i hidrotehnike, do te mere da su Rimljani preuzeli njihov sistem navodnjavanja. Porazili su Grke u tri odvojene bitke, a njihov kralj Obodas I porazio je i ubio seleukidskog kralja Antioha XII. Strabon beleži da je njihova prestonica Petra uživala dobru upravu.","headingId":"","headingText":""},{"text":"Poreklo i prvi pomeni Najstariji pomen Nabatejaca potiče iz 312. godine pre nove ere, gde se spominju kao nomadi koji žive u šatorima i trguju mirisima, aromatičnim biljem i začinima iz južne Arabije. Nabatejci su levantski arapski narod, među narodima Levanta. Nakon što su se urbanizovali, arapski Nabatejci postali su jedan od najistaknutijih naroda u istoriji civilizacije.","headingId":"poreklo-i-prvi-pomeni","headingText":"Poreklo i prvi pomeni"},{"text":"Umetnost i graditeljstvo Arapski Nabatejci imali su prefinjenu civilizaciju i bili su među najveštijim narodima u umetnosti, graditeljstvu i arhitekturi. Imali su snažan uticaj na svoje susede. Arhitektura poznata kao herodijanska arapska arhitektura, nazvana po Herodu, kralju Judeje arapskog edomitskog porekla, izvedena je iz tri graditeljska stila: helenističkog, rimskog i nabatejskog arapskog. Uticaj nabatejske umetnosti vidljiv je i na kapitelima stubova u tvrđavi Masada.","headingId":"umetnost-i-graditeljstvo","headingText":"Umetnost i graditeljstvo"},{"text":"Uprava i pravda Nabatejsko arapsko kraljevstvo bilo je poznato po pravdi. Istoričar Strabon zabeležio je da je prestonica nabatejskog kraljevstva, Petra, uživala dobru upravu. Strabon, Geografija. Posetioci su njihovu upravu opisivali sa divljenjem, a strancima koji su tamo boravili bilo je dozvoljeno da podnose tužbe. Kada bi, međutim, spor nastao među samim Nabatejcima, oni se nisu obraćali sudstvu, nego su ga rešavali drugim mirnim načinima.","headingId":"uprava-i-pravda","headingText":"Uprava i pravda"},{"text":"Nabatejci i Damask Damask je jedne od svojih najlepših dana proživeo pod nabatejskom vlašću. Među četiri arapska entiteta koja su okruživala Damask, upravo su arapski Nabatejci u tom razdoblju imali najveći uticaj na taj grad. To je bio nastavak njihove ranije vlasti nad Damaskom, uspostavljene nakon što su Nabatejci 87. godine pre nove ere porazili Seleukidsko carstvo. Stanovnici grada tada su dočekali kralja Aretu III, tražeći njegovu zaštitu, i Damaščani su živeli u miru.","headingId":"nabatejci-i-damask","headingText":"Nabatejci i Damask"},{"text":"Privreda, pismenost i tehnika Arapski nabatejski narod imao je razvijenu privredu, visoku pismenost i izuzetnu umetničku stvaralačku snagu. Nabatejci su bili majstori navodnjavanja i hidrotehnike, a Rimljani su preuzeli njihov sistem navodnjavanja.","headingId":"privreda-pismenost-i-tehnika","headingText":"Privreda, pismenost i tehnika"},{"text":"Pobede nad Grcima Arapski Nabatejci ostvarili su slavne pobede nad Grcima. Porazili su Grke u tri odvojene bitke i potpuno uništili njihove snage, tako da je preživelo tek nekoliko desetina onih koji su na konjima pobegli preko pustinje. Porazili su snage Atenarija i uništili čitavu njegovu vojsku. Antigon je zatim poslao još jednu silu da zauzme nabatejsko uporište, ali ni ona nije uspela. Vojskovođe tih vojski bili su generali Aleksandra Velikog, koji je pokorio sva kraljevstva starog sveta od Italije do Kine i uspostavio helenističko carstvo na tri kontinenta.","headingId":"pobede-nad-grcima","headingText":"Pobede nad Grcima"},{"text":"Bitka kod Kane Arapski Nabatejci pobedili su i u bici kod Kane, koja se odigrala 87. ili 84. godine pre nove ere protiv Seleukida. Kralj Obodas I naneo je ponižavajući poraz seleukidskom kralju Antiohu XII i pritom ga ubio.","headingId":"bitka-kod-kane","headingText":"Bitka kod Kane"}]},{"slug":"optuzbe-protiv-Osmana-ibn-Affana","chunks":[{"text":"Imam Ebu Bekr Ibn el Arebi el Maliki te tvrdnje ocenjuje kao daleke od istine i zasnovane na prenošenju lažljivaca, navodeći da je sve to neistinito i po senedu i po tekstu. Osman nije bio odgovoran za sve ono što je izazvalo gnev tih skupina. Buhari beleži da mu tokom dvanaest godina uprave niko ništa nije prigovarao, a verodostojni hadisi navode da mu je Poslanik ﷺ najavio da će preseliti kao nepravedno ubijen šehid.","headingId":"","headingText":""},{"text":"Primedba Prigovarači tvrde da je Osman ibn Affan tokom svog hilafeta činio nepravde i nedela, zbog čega je protiv njega izbila pobuna i zbog čega je ubijen.","headingId":"primedba","headingText":"Primedba"},{"text":"Odgovor Imam Ebu Bekr Ibn el Arebi el Maliki naveo je da su te tvrdnje daleke od istine i da počivaju na prenošenju lažljivaca, izjavivši: Sve je to neistinito i po svom senedu i po svom tekstu. Naglasio je da su tvrdnje o tome da je Osman činio nepravde neutemeljene i da su i pojedine odbrane od tih tvrdnji bile zasnovane na neistini. Ebu Bekr Ibn el Arebi el Maliki, El Avasim minel kavasim.","headingId":"odgovor","headingText":"Odgovor"},{"text":"Osman nije bio odgovoran Osman nije bio odgovoran za sve ono što je izazvalo gnev tih skupina. Buhari beleži: Zapovednik vernika, Osman ibn Affan, upravljao je dvanaest godina, a oni mu ništa nisu prigovarali. Izvor: Sahih Buhari. Sahih Buhari.","headingId":"osman-nije-bio-odgovoran","headingText":"Osman nije bio odgovoran"},{"text":"Njegovo ubistvo kao najavljena vest Njegova smrt bila je unapred najavljena. Verodostojni hadisi navode da je Poslanik ﷺ Osmanu dao radosnu vest da će preseliti kao nepravedno ubijen šehid, a Osman je bio i među desetericom kojima je obećan Džennet. Te činjenice protivreče tvrdnjama o nedelima kojima bi se opravdalo njegovo ubistvo.","headingId":"njegovo-ubistvo-kao-najavljena-vest","headingText":"Njegovo ubistvo kao najavljena vest"}]},{"slug":"Persija-pod-Sasanidima-i-dolazak-islama","chunks":[{"text":"Najveći deo prihoda Persijanaca tokom njihove vladavine dolazio je iz iračkih zemalja, gde su seljaci pod persijskom državom živeli u poretku bliskom ropstvu. Pismenost nije bila široko dostupna, nego skoncentrisana u uskom vladajućem sloju. Pod sasanidskom vlašću progonjeni su hrišćani, Jevreji, Sabejci, maniheji i budisti.","headingId":"","headingText":""},{"text":"Prihodi iz Iraka Najveći deo prihoda Persijanaca tokom čitave njihove vladavine nad narodima dolazio je iz iračkih zemalja, gde su seljaci pod persijskom državom živeli u poretku bliskom ropstvu. Hugh Kennedy, The Great Arab Conquests, str. 100.","headingId":"prihodi-iz-iraka","headingText":"Prihodi iz Iraka"},{"text":"Pismenost Pismenost u sasanidskom razdoblju nije bila široko dostupna, nego je bila skoncentrisana u uskom vladajućem sloju. Vesta Sarkhosh Curtis, The Sasanian Era, str. 151 152. Izvorni tekst ovo mesto navodi oštrije, kao zabranu čitanja i pisanja običnim ljudima. Sam izvor na koji se poziva, međutim, govori o tome da pismenost nije bila široko dostupna i da je bila skoncentrisana u eliti, pa je ovde preneseno onako kako izvor glasi.","headingId":"pismenost","headingText":"Pismenost"},{"text":"Verski progon Pod sasanidskom vlašću progonjeni su hrišćani, Jevreji, Sabejci, maniheji i budisti. T. W. Arnold, The Preaching of Islam, str. 206.","headingId":"verski-progon","headingText":"Verski progon"},{"text":"Pitanje kupanja i higijene Izvorni tekst na ovom mestu iznosi tvrdnju o higijenskim običajima starih Persijanaca koju navedeni izvor ne potkrepljuje. Odlomak kod Koso zapravo govori o zoroastrijskim shvatanjima obredne čistoće i o uzdržavanju od kupanja vodom zbog njegovog povezivanja sa hrišćanskim i rimskim običajima. Ta tvrdnja je zato ovde izostavljena.","headingId":"pitanje-kupanja-i-higijene","headingText":"Pitanje kupanja i higijene"}]},{"slug":"pisci-koji-su-govorili-o-Arapima-pre-islama","chunks":[{"text":"Ovo je hronološki popis pisaca koji Arape spominju pre islama. Niz počinje Homerom i Hekatejem iz Mileta, a proteže se kroz petnaest vekova, do Prokopija u šestom veku nove ere. Reč je o grčkim, rimskim, egipatskim, vavilonskim, feničanskim i jevrejskim piscima, dakle o svedočanstvima iz najrazličitijih sredina.","headingId":"","headingText":""},{"text":"Od devetog do petog veka pre nove ere 1. Homer, grčki pesnik 2. Hekatej iz Mileta, grčki istoričar i geograf 3. Herodot, grčki istoričar 4. Eshil, grčki pesnik","headingId":"od-devetog-do-petog-veka-pre-nove-ere","headingText":"Od devetog do petog veka pre nove ere"},{"text":"Od četvrtog do prvog veka pre nove ere 1. Ksenofont, grčki istoričar 2. Ktesija sa Knida, grčki istoričar 3. Pseudo Skilaks, grčki geograf 4. Zenon Stoik, feničanski filozof 5. Maneton iz Sebenita, egipatski istoričar 6. Beros Haldejac, vavilonski istoričar 7. Artapan iz Aleksandrije, jevrejski istoričar 8. Demetrije Hronograf, jevrejski istoričar 9. Eratosten, grčki geograf 10. Kleodem Malh, semitski istoričar 11. Polibije, grčki istoričar 12. Agatarhid sa Knida, grčki istoričar i geograf 13. Knjiga jubileja, jevrejski spis 14. Diodor Sicilijski, grčki istoričar i geograf 15. Posidonije iz Apameje, grčki istoričar 16. Katul, rimski pesnik 17. Ciceron, rimski političar i pisac","headingId":"od-cetvrtog-do-prvog-veka-pre-nove-ere","headingText":"Od četvrtog do prvog veka pre nove ere"},{"text":"Od prvog do šestog veka nove ere Niz se nastavlja kroz još pedesetak pisaca i dela, poređanih hronološki, među kojima su Strabon, Plinije Stariji, Josif Flavije, Tacit, Jeronim, Jevsevije Kesarijski i Prokopije. Izvorni popis u trećem razdoblju navodi imena bez pratećih podataka o delima, pa su ovde izdvojena samo ona koja su na izvornoj stranici jasno navedena.","headingId":"od-prvog-do-sestog-veka-nove-ere","headingText":"Od prvog do šestog veka nove ere"}]},{"slug":"predislamske-arapske-loze-i-brak-kod-Kurejsija","chunks":[{"text":"Kurejšije i Arapi nisu priznavali nijedan oblik braka osim onog zasnovanog na mehru, bračnom daru i svedocima. Sve drugo smatrali su bludom i razvratom. Retki pojedinačni slučajevi odstupanja nisu bili njihov izvorni običaj, bili su prezreni, a takvi su bili rašireni kod svih susednih naroda. Napade na arapske loze širili su Persijanci i nearapi neprijateljski raspoloženi prema Arapima u kasnijim razdobljima.","headingId":"","headingText":""},{"text":"Osnovna tvrdnja Kurejšije, kao ni bilo ko od Arapa, nisu priznavali ispravnost nijedne vrste braka osim onog zasnovanog na mehru i bračnom daru, uz svedoke, i to je bio preovlađujući oblik braka među njima, pa nijedan drugi nisu prihvatali. Sve drugo smatrali su bludom i razvratom. Ispravan brak kod Kurejšija i Arapa, dakle, iziskivao je mehr, bračni dar i svedoke.","headingId":"osnovna-tvrdnja","headingText":"Osnovna tvrdnja"},{"text":"Retka odstupanja Tačno je da su imali retke pojedinačne slučajeve, koji uprkos svojoj retkosti nisu bili njihov izvorni običaj, i koji su bili nepoželjni, a na one koji su ih činili gledalo se sa prezirom i omalovažavanjem. Ti postupci nisu bili njihov izvorni običaj, a bili su rašireni kod svih susednih naroda.","headingId":"retka-odstupanja","headingText":"Retka odstupanja"},{"text":"Južnoarapsko društvo Kod pojedinih tamošnjih zajednica bila je poznata poliandrija, gde jedna žena stupa u brak sa više muškaraca i sa njima ima decu. Reč je, dakle, o običaju vezanom za određene susedne zajednice, a ne o običaju Kurejšija niti o opštem arapskom običaju.","headingId":"juznoarapsko-drustvo","headingText":"Južnoarapsko društvo"},{"text":"Poreklo tih napada Napade na loze Arapa širili su Persijanci i nearapi neprijateljski raspoloženi prema Arapima, i to u kasnijim razdobljima, a ne savremenici tih događaja.","headingId":"poreklo-tih-napada","headingText":"Poreklo tih napada"},{"text":"Svedočanstvo Hinde bint Utbe Prilikom davanja prisege, Hinda bint Utba rekla je: Dajem ti prisegu pod uslovom da Allahu ništa ne pridružuješ, da ne kradeš i da ne bludničiš. O tome je rečeno i: „Čak i kada bi srca svih žena bila poput Hindinog srca, nijednu od njih ne bih optužio za blud.\" To svedočanstvo dolazi iz samog tog društva i pokazuje kakav je odnos prema tim pitanjima zaista bio.","headingId":"svedocanstvo-hinde-bint-utbe","headingText":"Svedočanstvo Hinde bint Utbe"}]},{"slug":"rani-sirijski-izvori-o-islamu","chunks":[{"text":"Islam nije izmišljen pod Abasijama. Sirijski hrišćanski spisi nastali pre 750. godine već ga prepoznaju, opisuju, raspravljaju s njim i odgovaraju mu. Reč je o nezavisnom svedočanstvu, jer ne potiče od muslimana, nego od hrišćanskih pisaca koji su živeli pod novom vlašću. Niz tih izvora datiran je već od 637. i 640. godine, dakle više od jednog veka pre abasijskog razdoblja.","headingId":"","headingText":""},{"text":"Tvrdnja o takozvanom abasijskom islamu Prema toj teoriji, islam u obliku u kojem ga poznajemo nije nastao u sedmom veku, nego je uobličen tek pod Abasijama, nakon 750. godine. Orijentalistima je ta teorija bila potrebna zato što bi, ako se rani izvori odbace kao pozni, čitava rana islamska istorija ostala bez potvrde.","headingId":"tvrdnja-o-takozvanom-abasijskom-islamu","headingText":"Tvrdnja o takozvanom abasijskom islamu"},{"text":"Zašto ranih islamskih zapisa ima malo Oskudnost ranih islamskih pisanih zapisa ima svoje istorijske razloge i ne dokazuje da islam tada nije postojao. Isti taj argument, primenjen dosledno, doveo bi u pitanje i mnoge druge istorijske pojave tog razdoblja.","headingId":"zasto-ranih-islamskih-zapisa-ima-malo","headingText":"Zašto ranih islamskih zapisa ima malo"},{"text":"Sirijski spisi kao nezavisno svedočanstvo Značaj sirijskih hrišćanskih spisa jeste u tome što oni nisu muslimanski izvori. Njih su pisali hrišćanski autori koji su živeli pod novom vlašću, često prema njoj neprijateljski raspoloženi, pa se njihovo svedočanstvo ne može odbaciti kao naknadno muslimansko uobličavanje. Na taj korpus posebno upućuje Majkl Filip Pen u svom radu o ranim sirijskim spisima o islamu. Michael Philip Penn, o ranim sirijskim spisima o islamu.","headingId":"sirijski-spisi-kao-nezavisno-svedocanstvo","headingText":"Sirijski spisi kao nezavisno svedočanstvo"},{"text":"Pregled izvora nastalih pre 750. godine 1. Zapis iz 637. godine i Hronika iz 640. godine , koje pripadaju najranijim svedočanstvima o arapskom osvajanju. 2. Pisma patrijarha Išojaba III , u kojima se spominju muslimani i njihov odnos prema hrišćanima. 3. Huzistanska hronika , kao i apokaliptički spisi tog razdoblja. 4. Maronitska hronika , u kojoj se muslimanska politička vlast prepoznaje kao ustanovljena. 5. Odluke sirijskog crkvenog sabora iz 676. godine , koje se odnose na život hrišćana pod muslimanskom vlašću. 6. Svedočanstvo Jovana ibn el Fankija iz 692. godine . 7. Kupola na steni i njeni natpisi, kao javno iskazan islamski identitet. 8. Spisi Jakova Edeskog , koji daju razložniju sliku islama. 9. Rasprave Jovana i emira , kao","headingId":"pregled-izvora-nastalih-pre-750-godine","headingText":"Pregled izvora nastalih pre 750. godine"},{"text":"i rasprava iz Bet Halea. 10. Spisi Hananišue I i Mar Abe II .","headingId":"pregled-izvora-nastalih-pre-750-godine","headingText":"Pregled izvora nastalih pre 750. godine"},{"text":"Prelazak sa sirijskog na arapski Postepen prelazak sa sirijskog na arapski jezik i sam je pokazatelj uspostavljene islamske vlasti i njenog uticaja, i to znatno pre abasijskog razdoblja.","headingId":"prelazak-sa-sirijskog-na-arapski","headingText":"Prelazak sa sirijskog na arapski"},{"text":"Zašto teorija o abasijskom islamu ne stoji Ti izvori, uzeti zajedno, pokazuju da je islam pre 750. godine već bio prepoznat, da ga se strahovalo, da se o njemu raspravljalo i da mu se odgovaralo, i to od strane hrišćanskih pisaca koji nisu imali nikakvog razloga da ga potvrđuju. Teorija koja islam smešta u abasijsko razdoblje mora, dakle, odbaciti čitav taj niz nezavisnih svedočanstava, i to bez ijednog dokaza da su ona naknadno sastavljena. Izvorni tekst ove izvore navodi po imenu i datumu, ali iz njih ne donosi doslovne navode. Za same navode potrebno je posegnuti za radom Majkla Filipa Pena, na koji se i sam poziva.","headingId":"zasto-teorija-o-abasijskom-islamu-ne-stoji","headingText":"Zašto teorija o abasijskom islamu ne stoji"}]}];
